/* Embedded outreach modules 13–30. Same scene structure as modules 03–12:
   a label, a precise title, a short explanation, a diagram, a takeaway, sources.
   Publisher of the pathway: CodexVitae ETS. */
Object.assign(additionalOutreachModules, {
  12: { title:'Quanto pesa l’AMR', label:'Tredicesimo modulo completo.', completion:'Sei scene per leggere mortalità e costi come stime con anno, controfattuale e popolazione, senza sommare studi diversi.', slides:[
    {label:'Due stime',title:'Associato e attribuibile non sono lo stesso numero',intro:'Nel 2019 il progetto GRAM ha stimato 4,95 milioni di decessi associati all’AMR batterica (intervallo di incertezza 3,62–6,57) e 1,27 milioni attribuibili (0,911–1,71). Il primo controfattuale toglie l’infezione; il secondo la lascia, ma suscettibile al farmaco.',visual:'<div class="impact-layout"><div class="impact-stat"><strong>4,95</strong><p>milioni di decessi associati, 2019. Controfattuale: nessuna infezione.</p><small>Intervallo 3,62–6,57 milioni. Stima di modello, non un conteggio di certificati.</small></div><div class="impact-stat"><strong>1,27</strong><p>milioni di decessi attribuibili, 2019. Controfattuale: infezione suscettibile.</p><small>Intervallo 0,911–1,71 milioni. Murray et al., Lancet 2022.</small></div></div>',takeaway:'Prima di citare un bilancio di morti, dichiarare l’anno, il controfattuale e l’intervallo.',sources:[['Murray et al. · Lancet 2022','https://doi.org/10.1016/S0140-6736(21)02724-0'],['WHO · AMR fact sheet','https://www.who.int/news-room/fact-sheets/detail/antimicrobial-resistance']]},
    {label:'Di che cosa è fatto',title:'Sei patogeni concentrano gran parte della stima globale',intro:'Gli stessi autori attribuiscono a Escherichia coli, Staphylococcus aureus, Klebsiella pneumoniae, Streptococcus pneumoniae, Acinetobacter baumannii e Pseudomonas aeruginosa 929.000 decessi attribuibili e 3,57 milioni associati. Una sola combinazione, Staphylococcus aureus resistente alla meticillina, supera 100.000 decessi attribuibili.',visual:'<div class="esk-grid"><article><b>Associati</b><strong>3,57 milioni</strong><p>i sei patogeni, 2019. Intervallo 2,62–4,78.</p></article><article><b>Attribuibili</b><strong>929.000</strong><p>i sei patogeni. Intervallo 660.000–1.270.000.</p></article><article><b>Una combinazione</b><strong>MRSA</strong><p>più di 100.000 decessi attribuibili nel 2019.</p></article></div>',takeaway:'La composizione della stima non è una classifica di ospedali né un dato sardo.',sources:[['Murray et al. · Lancet 2022','https://doi.org/10.1016/S0140-6736(21)02724-0']]},
    {label:'Europa',title:'L’ECDC stima un sottoinsieme, non tutta l’AMR',intro:'Per combinazioni batterio-antibiotico selezionate, nell’UE/SEE i decessi attribuibili stimati vanno da 30.730 nel 2016 a 38.710 nel 2019. La sintesi pubblica parla di più di 35.000 decessi l’anno. Il carico per popolazione risulta più alto in Grecia, Italia e Romania: non è un tasso della Sardegna.',visual:'<div class="compare-pair"><article><b>2016</b><strong>30.730</strong><p>decessi attribuibili. Intervallo 26.935–34.836.</p></article><i aria-hidden="true">→</i><article><b>2019</b><strong>38.710</strong><p>decessi attribuibili. Intervallo 34.053–43.748.</p></article></div>',takeaway:'Il confronto con GRAM non è lecito: popolazione, patogeni e metodo non coincidono.',sources:[['ECDC · Burden 2016–2020','https://www.ecdc.europa.eu/en/publications-data/health-burden-infections-antibiotic-resistant-bacteria-2016-2020'],['ECDC · EAAD 2022','https://www.ecdc.europa.eu/en/news-events/eaad-2022-launch']]},
    {label:'Dove pesa',title:'La quota associata all’assistenza riguarda i casi del modello',intro:'Nel rapporto ECDC il 70,9% dei casi stimati (intervallo di confidenza al 95% 68,2–74,0) è collegato all’assistenza sanitaria. È una proprietà di quelle infezioni nel modello, non la frazione di un reparto o di un territorio.',visual:'<div class="denominator-card"><strong>70,9%</strong><span>dei casi stimati, associati all’assistenza</span><hr><span>IC 95% 68,2–74,0 · combinazioni incluse nello studio</span><b>non è una prevalenza locale</b></div>',takeaway:'Una percentuale di un modello europeo non si trasferisce a una struttura senza il suo denominatore.',sources:[['ECDC · Burden 2016–2020','https://www.ecdc.europa.eu/en/publications-data/health-burden-infections-antibiotic-resistant-bacteria-2016-2020']]},
    {label:'I costi',title:'Il costo OECD è un’altra stima, in un’altra unità',intro:'Il modello OECD del 2018 valuta la spesa sanitaria corrente dovuta all’AMR in circa 3,5 miliardi di dollari a parità di potere d’acquisto l’anno nei 33 Paesi inclusi, di cui circa 1,5 miliardi nell’UE/SEE. Sono dollari PPP del 2017, non euro di bilancio e non si sommano ai decessi.',visual:'<div class="system-compare"><article><b>33 Paesi</b><span>3,5 miliardi</span><small>USD PPP l’anno</small></article><article><b>UE/SEE</b><span>1,5 miliardi</span><small>USD PPP l’anno</small></article><article><b>Unità</b><span>USD PPP 2017</span><small>modello OECD 2018</small></article></div>',takeaway:'Mortalità e costo restano affiancati, ciascuno con la propria fonte.',sources:[['OECD · Stemming the Superbug Tide, 2018','https://www.oecd.org/en/publications/stemming-the-superbug-tide_9789264307599-en.html']]},
    {label:'Un aggiornamento',title:'Un anno diverso produce un numero diverso',intro:'La stima GBD per il 2021 riporta 4,71 milioni di decessi associati e 1,14 milioni attribuibili. Non sostituisce in silenzio il 2019 e non si media con quello. L’OMS richiama le stime GRAM come ordine di grandezza globale, non come tasso locale.',visual:'<div class="quote-panel"><p>2019</p><span>4,95 milioni associati · 1,27 milioni attribuibili</span><hr><p>2021</p><span>4,71 milioni associati · 1,14 milioni attribuibili</span><hr><p>Lettura</p><span>stesso tipo di domanda, anno e modello da dichiarare</span></div>',takeaway:'Citare il numero insieme allo studio. Non costruire un totale tra pubblicazioni.',sources:[['GBD 2021 AMR Collaborators · Lancet 2024','https://doi.org/10.1016/S0140-6736(24)01867-1'],['WHO · AMR fact sheet','https://www.who.int/news-room/fact-sheets/detail/antimicrobial-resistance']]}
  ]},
  13: { title:'Le priorità OMS', label:'Quattordicesimo modulo completo.', completion:'Sei scene per leggere la Bacterial Priority Pathogens List 2024 come bussola di ricerca e sanità pubblica, non come graduatoria locale.', slides:[
    {label:'Lo strumento',title:'La lista ordina priorità, non misura un territorio',intro:'La WHO BPPL 2024 aggiorna la lista del 2017. L’OMS la descrive come copertura di 24 patogeni in 15 famiglie, suddivisi in priorità critica, alta e media, per orientare ricerca, sviluppo e misure di sanità pubblica.',visual:'<div class="bppl-cols"><article class="priority-critical"><b>Critica</b><strong>Ultima risorsa e carico</strong><p>Gram-negativi resistenti a farmaci di ultima linea, e tubercolosi resistente alla rifampicina.</p></article><article class="priority-high"><b>Alta</b><strong>Carico e opzioni che si restringono</strong><p>Enterococchi, stafilococchi, Pseudomonas, enterici e gonococco.</p></article><article class="priority-medium"><b>Media</b><strong>Impatto in popolazioni vulnerabili</strong><p>Streptococchi e Haemophilus, con resistenze definite.</p></article></div>',takeaway:'La priorità è un giudizio multicriterio globale. Non è la frequenza di un laboratorio.',sources:[['WHO · BPPL 2024','https://www.who.int/publications/i/item/9789240093461'],['WHO · Aggiornamento 17 maggio 2024','https://www.who.int/news/item/17-05-2024-who-updates-list-of-drug-resistant-bacteria-most-threatening-to-human-health']]},
    {label:'Priorità critica',title:'Quattro gruppi, di cui uno con un metodo a parte',intro:'In priorità critica stanno Acinetobacter baumannii resistente ai carbapenemi, gli Enterobacterales resistenti alle cefalosporine di terza generazione e gli Enterobacterales resistenti ai carbapenemi. Mycobacterium tuberculosis resistente alla rifampicina è stato incluso dopo un’analisi indipendente, con criteri adattati.',visual:'<div class="checklist-visual"><span>A. baumannii · carbapenemi</span><span>Enterobacterales · cefalosporine di III generazione</span><span>Enterobacterales · carbapenemi</span><span>M. tuberculosis · rifampicina</span><strong>priorità critica · WHO BPPL 2024</strong></div>',takeaway:'La tubercolosi resistente alla rifampicina è nel gruppo critico, ma non è il prodotto della stessa matrice decisionale degli altri tre.',sources:[['WHO · Aggiornamento 17 maggio 2024','https://www.who.int/news/item/17-05-2024-who-updates-list-of-drug-resistant-bacteria-most-threatening-to-human-health']]},
    {label:'Priorità alta',title:'Sette combinazioni con domande di salute diverse',intro:'Il gruppo alto affianca infezioni invasive nosocomiali e patogeni a trasmissione enterica o sessuale. La lista non dice che abbiano lo stesso meccanismo né la stessa terapia.',visual:'<ul class="bppl-names"><li>Salmonella Typhi resistente ai fluorochinoloni</li><li>Shigella spp. resistente ai fluorochinoloni</li><li>Enterococcus faecium resistente alla vancomicina</li><li>Pseudomonas aeruginosa resistente ai carbapenemi</li><li>Salmonella non tifoidee resistenti ai fluorochinoloni</li><li>Neisseria gonorrhoeae resistente alle cefalosporine di terza generazione e/o ai fluorochinoloni</li><li>Staphylococcus aureus resistente alla meticillina</li></ul>',takeaway:'Leggere ogni riga come coppia patogeno-resistenza, non come un unico “batterio prioritario”.',sources:[['WHO · BPPL 2024','https://www.who.int/publications/i/item/9789240093461']]},
    {label:'Priorità media',title:'Media non significa trascurabile',intro:'Nel gruppo medio l’OMS colloca streptococchi di gruppo A resistenti ai macrolidi, Streptococcus pneumoniae resistente ai macrolidi, Haemophilus influenzae resistente all’ampicillina e streptococchi di gruppo B resistenti alla penicillina. La motivazione pubblicata è l’impatto in popolazioni vulnerabili e in contesti con poche risorse.',visual:'<div class="matrix-grid"><span>Gruppo A · macrolidi</span><span>S. pneumoniae · macrolidi</span><span>H. influenzae · ampicillina</span><b>Gruppo B · penicillina · priorità media</b></div>',takeaway:'Il grado descrive la priorità di ricerca e controllo, non la gravità del singolo paziente.',sources:[['WHO · Aggiornamento 17 maggio 2024','https://www.who.int/news/item/17-05-2024-who-updates-list-of-drug-resistant-bacteria-most-threatening-to-human-health']]},
    {label:'A che cosa serve',title:'Orienta la pipeline e la sorveglianza, non la prescrizione del caso',intro:'L’OMS indica trasferibilità dei geni, gravità, carico e trattabilità tra le ragioni del gruppo critico. Nessuna di queste ragioni sceglie l’antibiotico di una persona. Quella scelta resta clinica, con linee guida e antibiogramma.',visual:'<div class="evidence-ladder"><span>lista globale</span><i>→</i><span>domanda di ricerca</span><i>→</i><span>sorveglianza locale</span><i>→</i><strong>decisione clinica a parte</strong></div>',takeaway:'Una priorità OMS non è un prontuario e non è una mappa.',sources:[['WHO · BPPL 2024','https://www.who.int/publications/i/item/9789240093461']]},
    {label:'Il limite',title:'La lista globale va contestualizzata',intro:'Lo stesso documento avverte che distribuzione, ecologia e gruppi vulnerabili cambiano tra regioni, e che le strategie vanno adattate. Una specie in priorità critica può essere rara in un laboratorio, e una in priorità media può essere frequente.',visual:'<div class="quote-panel"><p>Globale</p><span>criteri e gruppi pubblicati dall’OMS</span><hr><p>Locale</p><span>copertura, denominatore, periodo della sorveglianza</span><hr><p>Non dedurre</p><span>la frequenza sarda dalla posizione nella lista</span></div>',takeaway:'La BPPL dice dove guardare. I dati locali dicono che cosa si osserva.',sources:[['WHO · BPPL 2024','https://www.who.int/publications/i/item/9789240093461']]}
  ]},
  14: { title:'ESKAPE', label:'Quindicesimo modulo completo.', completion:'Sei scene per usare l’acronimo come elenco di patogeni nosocomiali, senza farne un unico meccanismo né una diagnosi.', slides:[
    {label:'Le sei lettere',title:'L’acronimo nomina sei batteri, non una sindrome',intro:'ESKAPE riunisce Enterococcus faecium, Staphylococcus aureus, Klebsiella pneumoniae, Acinetobacter baumannii, Pseudomonas aeruginosa ed Enterobacter spp. Il termine è entrato nella letteratura delle infezioni nosocomiali con Rice nel 2008 e con la nota dell’Infectious Diseases Society of America nel 2009.',visual:'<div class="esk-grid"><article><b>E</b><strong>E. faecium</strong></article><article><b>S</b><strong>S. aureus</strong></article><article><b>K</b><strong>K. pneumoniae</strong></article><article><b>A</b><strong>A. baumannii</strong></article><article><b>P</b><strong>P. aeruginosa</strong></article><article><b>E</b><strong>Enterobacter spp.</strong></article></div>',takeaway:'Sciogliere sempre l’acronimo. Due specie dello stesso genere non sono intercambiabili.',sources:[['Rice · J Infect Dis 2008','https://doi.org/10.1086/533452'],['Boucher et al. · Clin Infect Dis 2009','https://doi.org/10.1086/595011']]},
    {label:'Perché contano',title:'Sono frequenti in ospedale e accumulano più di un meccanismo',intro:'La letteratura li mette insieme perché causano infezioni associate all’assistenza e perché, in modi diversi, riducono le opzioni terapeutiche: acquisizione di geni, modifica del bersaglio, pompe, porine. L’acronimo non assegna a tutti lo stesso fenotipo.',visual:'<div class="mechanism-grid"><article><strong>Contesto</strong><p>Infezioni associate all’assistenza, non un serbatoio unico.</p></article><article><strong>Meccanismi</strong><p>Più di una via, spesso insieme, da specie a specie.</p></article><article><strong>Limite</strong><p>L’etichetta non sostituisce specie, farmaco e antibiogramma.</p></article></div>',takeaway:'“È un ESKAPE” non è un referto.',sources:[['Boucher et al. · Clin Infect Dis 2009','https://doi.org/10.1086/595011'],['WHO · BPPL 2024','https://www.who.int/publications/i/item/9789240093461']]},
    {label:'E la lista OMS',title:'Il confronto con la BPPL 2024 è per coppie, non per sigla',intro:'Nella priorità critica o alta compaiono A. baumannii resistente ai carbapenemi, K. pneumoniae dentro gli Enterobacterales resistenti, P. aeruginosa resistente ai carbapenemi, E. faecium resistente alla vancomicina e S. aureus resistente alla meticillina. Enterobacter spp. non ha una riga propria: rientra negli Enterobacterales.',visual:'<div class="checklist-visual"><span>CRAB · critica</span><span>CRE, inclusa K. pneumoniae · critica</span><span>CRPA · alta</span><span>VRE faecium · alta</span><span>MRSA · alta</span><strong>Enterobacter · dentro Enterobacterales, non una riga separata</strong></div>',takeaway:'L’acronimo e la BPPL si intersecano. Non sono lo stesso elenco.',sources:[['WHO · BPPL 2024','https://www.who.int/publications/i/item/9789240093461'],['Rice · J Infect Dis 2008','https://doi.org/10.1086/533452']]},
    {label:'E il carico GRAM',title:'Quattro dei sei patogeni principali sono nell’acronimo',intro:'Tra i sei patogeni che nel 2019 concentrano la mortalità associata stimata da GRAM, S. aureus, K. pneumoniae, A. baumannii e P. aeruginosa sono ESKAPE. E. coli e S. pneumoniae no. Un acronimo ospedaliero non esaurisce il carico globale.',visual:'<div class="conclusion-board"><span class="yes">S. aureus</span><span class="yes">K. pneumoniae</span><span class="yes">A. baumannii</span><span class="yes">P. aeruginosa</span><span class="no">E. coli · fuori dall’acronimo</span><span class="no">S. pneumoniae · fuori dall’acronimo</span></div>',takeaway:'Ciò che l’acronimo lascia fuori può pesare quanto ciò che include.',sources:[['Murray et al. · Lancet 2022','https://doi.org/10.1016/S0140-6736(21)02724-0']]},
    {label:'Dentro la sigla',title:'Ogni lettera ha resistenze che non valgono per le altre',intro:'La meticillino-resistenza di S. aureus, la vancomicino-resistenza di E. faecium e le carbapenemasi di Klebsiella, Acinetobacter o Pseudomonas non sono lo stesso evento molecolare. I moduli successivi li separano.',visual:'<div class="evidence-ladder"><span>specie</span><i>→</i><span>farmaco</span><i>→</i><span>meccanismo</span><i>→</i><strong>fenotipo misurato</strong></div>',takeaway:'Non trasferire il meccanismo di una lettera all’altra.',sources:[['Blair et al. · Nat Rev Microbiol 2015','https://doi.org/10.1038/nrmicro3380']]},
    {label:'Come usarlo',title:'L’acronimo è un indice, non una conclusione',intro:'Serve a ricordare quali patogeni nosocomiali hanno più vie di fuga dai farmaci disponibili. Non localizza un focolaio, non stabilisce la terapia e non dice se un isolato sia resistente.',visual:'<div class="quote-panel"><p>Utile</p><span>per non dimenticare sei patogeni dell’assistenza</span><hr><p>Insufficiente</p><span>per un referto, una mappa o una priorità locale</span></div>',takeaway:'Dopo l’acronimo servono specie, farmaco, metodo e denominatore.',sources:[['Rice · J Infect Dis 2008','https://doi.org/10.1086/533452'],['WHO · BPPL 2024','https://www.who.int/publications/i/item/9789240093461']]}
  ]},
  15: { title:'Resistenza intrinseca e acquisita', label:'Sedicesimo modulo completo.', completion:'Sei scene per distinguere un tratto della specie da un tratto comparso in un lignaggio, prima di interpretare un antibiogramma.', slides:[
    {label:'Due origini',title:'Lo stesso fenotipo può avere storie diverse',intro:'Una resistenza intrinseca appartiene alla specie o al gruppo: il bersaglio manca, non è raggiungibile, o è poco affine. Una resistenza acquisita compare in una parte della popolazione, per mutazione o per DNA ricevuto da un’altra cellula.',visual:'<div class="compare-pair"><article><b>Intrinseca</b><strong>Tratto del gruppo</strong><p>Attesa anche senza esposizione recente di quel ceppo.</p></article><i aria-hidden="true">↔</i><article><b>Acquisita</b><strong>Tratto del lignaggio</strong><p>Mutazione oppure gene o elemento acquisito.</p></article></div>',takeaway:'“Resistente” senza questa distinzione mescola biologia della specie e evento evolutivo.',sources:[['Blair et al. · Nat Rev Microbiol 2015','https://doi.org/10.1038/nrmicro3380'],['Munita e Arias · Microbiol Spectr 2016','https://doi.org/10.1128/microbiolspec.VMBF-0016-2015']]},
    {label:'Esempi intrinseci',title:'Manca il bersaglio, oppure il farmaco non arriva',intro:'I micoplasmi non hanno parete di peptidoglicano: i β-lattamici non hanno il sito su cui agire. La membrana esterna dei Gram-negativi limita l’accesso di molecole grandi come i glicopeptidi. Sono proprietà del gruppo, non un fallimento della cura di quel paziente.',visual:'<div class="mechanism-grid"><article><strong>Bersaglio assente</strong><p>Micoplasmi e β-lattamici: non c’è la parete da inibire.</p></article><article><strong>Accesso impedito</strong><p>Gram-negativi e glicopeptidi: la membrana esterna fa da barriera.</p></article><article><strong>Affinità di specie</strong><p>PBP poco affini alle cefalosporine negli enterococchi.</p></article></div>',takeaway:'Un farmaco inattivo su un intero gruppo non documenta, da solo, una resistenza acquisita.',sources:[['Munita e Arias · Microbiol Spectr 2016','https://doi.org/10.1128/microbiolspec.VMBF-0016-2015'],['Li, Plésiat e Nikaido · Clin Microbiol Rev 2015','https://doi.org/10.1128/CMR.00117-14']]},
    {label:'Esempi acquisiti',title:'Mutazione e gene nuovo non sono sinonimi',intro:'Una mutazione può modificare il bersaglio, una porina o il regolatore di una pompa, e restare sul cromosoma. Un gene acquisito, per esempio una β-lattamasi su un plasmide, può entrare in una cellula che non lo aveva. Le due vie possono poi coesistere.',visual:'<div class="selection-flow"><span>mutazione</span><i>→</i><span>cromosoma</span><i>+</i><span>gene acquisito</span><i>→</i><span>elemento mobile</span></div>',takeaway:'Dire “genetico” non basta: cromosoma, plasmide e cassetta rispondono a domande diverse.',sources:[['Blair et al. · Nat Rev Microbiol 2015','https://doi.org/10.1038/nrmicro3380'],['Partridge et al. · Clin Microbiol Rev 2018','https://doi.org/10.1128/CMR.00088-17']]},
    {label:'A che cosa serve saperlo',title:'I fenotipi attesi controllano la lettura del test',intro:'EUCAST pubblica regole da esperto e fenotipi attesi proprio per confrontare il risultato con ciò che è tipico della specie. Un risultato incompatibile con il tratto atteso può indicare un errore di identificazione o di test, non automaticamente un nuovo meccanismo.',visual:'<div class="clinical-path"><article><span>01</span><strong>Identificare</strong><p>la specie</p></article><i>→</i><article><span>02</span><strong>Confrontare</strong><p>con il fenotipo atteso</p></article><i>→</i><article><span>03</span><strong>Interpretare</strong><p>ciò che eccede l’atteso</p></article></div>',takeaway:'La tabella dei fenotipi attesi è un controllo di qualità del dato, non una terapia.',sources:[['EUCAST · Expert rules','https://www.eucast.org/bacteria/important-additional-information/expert-rules/'],['EUCAST · Clinical breakpoints','https://www.eucast.org/clinical_breakpoints/']]},
    {label:'Insieme',title:'Intrinseco e acquisito si sommano nel fenotipo',intro:'Una specie già poco permeabile può acquisire una carbapenemasi, oppure perdere una porina. Il referto “resistente al carbapeneme” non dice quale dei due contributi prevale. Per saperlo servono il test e, se la domanda lo richiede, il gene.',visual:'<div class="risk-chain"><span>tratto di specie</span><i>→</i><span>evento acquisito</span><i>→</i><strong>fenotipo</strong><small>il totale non identifica l’addendo</small></div>',takeaway:'Il fenotipo è la somma misurata. Il meccanismo è un’ipotesi da sostenere.',sources:[['Blair et al. · Nat Rev Microbiol 2015','https://doi.org/10.1038/nrmicro3380']]},
    {label:'La frase completa',title:'Resistente a che cosa, e rispetto a quale attesa',intro:'Una frase utilizzabile nomina la specie, il farmaco, il metodo e se il risultato era atteso per quel gruppo. Senza questi quattro elementi il dato non si confronta.',visual:'<div class="quote-panel"><p>Specie</p><span>di quale organismo si parla</span><hr><p>Farmaco e metodo</p><span>quale molecola, quale standard</span><hr><p>Atteso o acquisito</p><span>tratto del gruppo, oppure evento del lignaggio</span></div>',takeaway:'La distinzione evita di trattare un tratto di specie come un’epidemia, e un gene nuovo come una curiosità.',sources:[['EUCAST · Expert rules','https://www.eucast.org/bacteria/important-additional-information/expert-rules/'],['Munita e Arias · Microbiol Spectr 2016','https://doi.org/10.1128/microbiolspec.VMBF-0016-2015']]}
  ]},
  16: { title:'Antibiotici di ultima linea', label:'Diciassettesimo modulo completo.', completion:'Sei scene per collocare carbapenemi e colistina nella stewardship, senza confondere spettro, gruppo AWaRe e meccanismo di resistenza.', slides:[
    {label:'Il nome',title:'Ultima linea è una categoria d’uso, non una potenza',intro:'In stewardship, un farmaco di ultima linea è tenuto per infezioni in cui le alternative sono inadeguate, non perché sia “più forte” in assoluto. L’OMS formalizza questa idea nei gruppi AWaRe: Access, Watch e Reserve.',visual:'<div class="aware-strip"><span><b>Access</b>prima scelta quando è appropriata</span><span><b>Watch</b>uso da sorvegliare</span><span><b>Reserve</b>riservato a infezioni da patogeni multiresistenti</span></div>',takeaway:'Il gruppo AWaRe non è una scala di efficacia clinica universale.',sources:[['Zanichelli et al. · Bull World Health Organ 2023','https://doi.org/10.2471/BLT.22.288614'],['WHO · AWaRe antibiotic book','https://www.who.int/publications/i/item/9789240061829']]},
    {label:'I carbapenemi',title:'Sono β-lattamici con uno spettro ampio e un gruppo AWaRe preciso',intro:'Meropenem, imipenem ed ertapenem restano β-lattamici: inibiscono le PBP. Sono stabili verso molte β-lattamasi, non verso le carbapenemasi. Nella lista modello OMS del 2021 il meropenem è nel gruppo Watch. Meropenem-vaborbactam, che è un’associazione, è nel gruppo Reserve.',visual:'<div class="compare-pair"><article><b>Meropenem</b><strong>Watch</strong><p>Carbapeneme. Non è nel gruppo Reserve.</p></article><i aria-hidden="true">≠</i><article><b>Meropenem-vaborbactam</b><strong>Reserve</strong><p>Associazione. Non è il meropenem da solo.</p></article></div>',takeaway:'Aggiungere un inibitore cambia la categoria e la domanda clinica. Non si abbrevia.',sources:[['Zanichelli et al. · Bull World Health Organ 2023','https://doi.org/10.2471/BLT.22.288614'],['Tooke et al. · J Mol Biol 2019','https://doi.org/10.1016/j.jmb.2019.04.002']]},
    {label:'La colistina',title:'È una polimixina del gruppo Reserve',intro:'Colistina e polimixina B sono nel gruppo Reserve della lista modello OMS 2021. Agiscono sulla membrana, modificando l’interazione con il lipide A, non sulla parete come i β-lattamici. Tossicità e indicazioni ne fanno farmaci di uso ristretto, non una scorciatoia.',visual:'<div class="mechanism-grid"><article><strong>Bersaglio</strong><p>Lipide A della membrana esterna dei Gram-negativi.</p></article><article><strong>Gruppo AWaRe</strong><p>Reserve, insieme alla polimixina B.</p></article><article><strong>Non è</strong><p>Un β-lattamico, né un carbapeneme “più potente”.</p></article></div>',takeaway:'Carbapeneme e colistina non si sostituiscono: bersaglio, tossicità e resistenze sono diversi.',sources:[['Zanichelli et al. · Bull World Health Organ 2023','https://doi.org/10.2471/BLT.22.288614'],['Liu et al. · Lancet Infect Dis 2016','https://doi.org/10.1016/S1473-3099(15)00424-7']]},
    {label:'Come si perde l’attività',title:'Le vie di resistenza non sono una sola',intro:'Un carbapeneme può essere idrolizzato da una carbapenemasi, oppure raggiungere meno il bersaglio se una porina manca e una β-lattamasi è già presente. La colistina può trovare un lipide A modificato, per via cromosomica o per un gene mcr plasmidico. Sono percorsi distinti.',visual:'<div class="four-domain-grid"><article><b>Carbapeneme</b><p>carbapenemasi</p></article><article><b>Carbapeneme</b><p>porina ridotta e β-lattamasi</p></article><article><b>Colistina</b><p>modifica cromosomica del lipide A</p></article><article><b>Colistina</b><p>mcr, su elemento mobile</p></article></div>',takeaway:'“Resistente ai carbapenemi” non implica un gene, e non implica resistenza alla colistina.',sources:[['Queenan e Bush · Clin Microbiol Rev 2007','https://doi.org/10.1128/CMR.00001-07'],['Liu et al. · Lancet Infect Dis 2016','https://doi.org/10.1016/S1473-3099(15)00424-7'],['Li, Plésiat e Nikaido · Clin Microbiol Rev 2015','https://doi.org/10.1128/CMR.00117-14']]},
    {label:'Chi decide',title:'La scelta resta una decisione clinica locale',intro:'Gruppo AWaRe, priorità OMS e antibiogramma rispondono a tre domande diverse: come sorvegliare i consumi, dove orientare la ricerca, se quell’isolato risponde a quella molecola. Nessuna delle tre prescrive al posto del curante.',visual:'<div class="clinical-path"><article><span>01</span><strong>AWaRe</strong><p>stewardship dei consumi</p></article><i>→</i><article><span>02</span><strong>BPPL</strong><p>priorità di ricerca</p></article><i>→</i><article><span>03</span><strong>Antibiogramma</strong><p>quell’isolato, quel farmaco</p></article></div>',takeaway:'Tenere separate le tre domande evita di usare una lista globale come referto.',sources:[['WHO · AWaRe antibiotic book','https://www.who.int/publications/i/item/9789240061829'],['EUCAST · Clinical breakpoints','https://www.eucast.org/clinical_breakpoints/']]},
    {label:'Che cosa proteggere',title:'Proteggere una molecola significa non sprecarne l’indicazione',intro:'Diagnostica, revisione della terapia e prevenzione delle infezioni riducono le occasioni in cui un Watch o un Reserve è l’unica via rimasta. Non esiste un gesto unico che “salvi” la colistina.',visual:'<div class="quote-panel"><p>Watch</p><span>meropenem: uso da motivare e da contare</span><hr><p>Reserve</p><span>colistina e alcune associazioni: uso ristretto</span><hr><p>Dato necessario</p><span>farmaco, indicazione, esito del test</span></div>',takeaway:'La tutela di queste molecole è un fatto organizzativo, documentabile, non uno slogan.',sources:[['Zanichelli et al. · Bull World Health Organ 2023','https://doi.org/10.2471/BLT.22.288614']]}
  ]},
  17: { title:'Enzimi che inattivano l’antibiotico', label:'Diciottesimo modulo completo.', completion:'Sei scene per separare classe di Ambler, descrizione funzionale (ESBL, carbapenemasi) e fenotipo misurato.', slides:[
    {label:'La reazione',title:'Una β-lattamasi apre l’anello da cui il farmaco dipende',intro:'I β-lattamici agiscono perché l’anello a quattro termini resta integro abbastanza da bloccare le PBP. Una β-lattamasi idrolizza quell’anello. Il nome dell’enzima dice quale famiglia chimica è in gioco, non quale sarà la MIC.',visual:'<div class="selection-flow"><span>β-lattame integro</span><i>→</i><span>idrolisi</span><i>→</i><span>anello aperto</span></div><p class="sci-caption">Schema della reazione. Non è una struttura molecolare risolta.</p>',takeaway:'Inattivare la molecola è un meccanismo. Non è l’unico, e non è automatico in ogni specie.',sources:[['Tooke et al. · J Mol Biol 2019','https://doi.org/10.1016/j.jmb.2019.04.002']]},
    {label:'Classi di Ambler',title:'Quattro classi strutturali, non quattro gravità',intro:'La classificazione di Ambler raggruppa le β-lattamasi per struttura del sito attivo. Le classi A, C e D sono seriniche. La classe B è metallo-dipendente e usa zinco. La classe non è una prognosi.',visual:'<div class="ambler-grid"><article><b>A · serina</b><strong>TEM, SHV, CTX-M, KPC</strong><p>Include ESBL e la carbapenemasi KPC.</p></article><article><b>B · metallo</b><strong>NDM, VIM, IMP</strong><p>Lo zinco è nel sito attivo. Non è inibita come le seriniche.</p></article><article><b>C · serina</b><strong>AmpC</strong><p>Cefalosporinasi, spesso cromosomiche e inducibili.</p></article><article><b>D · serina</b><strong>OXA, OXA-48-like</strong><p>Include carbapenemasi con idrolisi debole dei carbapenemi.</p></article></div>',takeaway:'KPC, NDM e OXA-48 idrolizzano carbapenemi e appartengono a classi diverse.',sources:[['Tooke et al. · J Mol Biol 2019','https://doi.org/10.1016/j.jmb.2019.04.002'],['Queenan e Bush · Clin Microbiol Rev 2007','https://doi.org/10.1128/CMR.00001-07']]},
    {label:'ESBL',title:'ESBL è una funzione, non una classe di Ambler',intro:'Per β-lattamasi a spettro esteso si intendono enzimi, in larga parte di classe A, che idrolizzano le cefalosporine ossimmino e sono inibiti dall’acido clavulanico. CTX-M, e varianti di TEM e SHV, sono le famiglie più citate. Un’ESBL non è, per definizione, una carbapenemasi.',visual:'<div class="mechanism-grid"><article><strong>Substrati tipici</strong><p>Penicilline e cefalosporine a spettro esteso, aztreonam.</p></article><article><strong>Inibizione</strong><p>Clavulanato, nel profilo classico di laboratorio.</p></article><article><strong>Non implica</strong><p>Idrolisi dei carbapenemi, né un plasmide dimostrato.</p></article></div>',takeaway:'Scrivere ESBL senza la famiglia (CTX-M, TEM, SHV) perde informazione, ma la famiglia non sostituisce l’antibiogramma.',sources:[['Paterson e Bonomo · Clin Microbiol Rev 2005','https://doi.org/10.1128/CMR.18.4.657-686.2005']]},
    {label:'Carbapenemasi',title:'Anche carbapenemasi è una funzione, e attraversa le classi',intro:'KPC è di classe A, NDM, VIM e IMP sono metallo-β-lattamasi, OXA-48-like è di classe D. Gli inibitori delle serin-β-lattamasi non coprono le metallo-β-lattamasi. OXA-48 idrolizza i carbapenemi in modo debole e spesso risparmia le cefalosporine a spettro esteso, se non è accompagnata da un’altra β-lattamasi.',visual:'<div class="system-compare"><article><b>KPC</b><span>classe A</span><small>serinica</small></article><article><b>NDM · VIM · IMP</b><span>classe B</span><small>zinco</small></article><article><b>OXA-48-like</b><span>classe D</span><small>idrolisi debole</small></article></div>',takeaway:'Il nome della carbapenemasi cambia l’ipotesi sull’inibitore. Non cambia, da solo, la condotta.',sources:[['Queenan e Bush · Clin Microbiol Rev 2007','https://doi.org/10.1128/CMR.00001-07'],['Tooke et al. · J Mol Biol 2019','https://doi.org/10.1016/j.jmb.2019.04.002']]},
    {label:'Gene e MIC',title:'Il gene rende plausibile un meccanismo, non misura la MIC',intro:'Un blaCTX-M o un blaKPC rilevato dice che quel determinante è nel materiale esaminato. Espressione, copie, porine e altre β-lattamasi spostano la concentrazione inibente. Per questo EUCAST interpreta la cura sul fenotipo e usa alcuni meccanismi come informazione aggiuntiva.',visual:'<div class="evidence-ladder"><span>sequenza</span><i>→</i><span>enzima possibile</span><i>→</i><span>contesto della cellula</span><i>→</i><strong>fenotipo</strong></div>',takeaway:'Non sostituire la lettera dell’enzima alla categoria S, I o R.',sources:[['EUCAST · Clinical breakpoints','https://www.eucast.org/clinical_breakpoints/'],['Paterson e Bonomo · Clin Microbiol Rev 2005','https://doi.org/10.1128/CMR.18.4.657-686.2005']]},
    {label:'Tre parole',title:'Classe, funzione e fenotipo vanno tenute in fila',intro:'Ambler risponde a “com’è fatto il sito attivo”. ESBL o carbapenemasi rispondono a “quali farmaci idrolizza, in quale profilo”. S, I e R rispondono a “che cosa ha misurato il test, con quale soglia”.',visual:'<div class="quote-panel"><p>Classe</p><span>A, B, C o D</span><hr><p>Funzione</p><span>ESBL, AmpC, carbapenemasi</span><hr><p>Fenotipo</p><span>categoria interpretativa per quel farmaco</span></div>',takeaway:'Una frase sola che mescola le tre parole non si può verificare.',sources:[['Tooke et al. · J Mol Biol 2019','https://doi.org/10.1016/j.jmb.2019.04.002'],['EUCAST · Clinical breakpoints','https://www.eucast.org/clinical_breakpoints/']]}
  ]},
  18: { title:'Bersagli modificati', label:'Diciannovesimo modulo completo.', completion:'Sei scene per seguire tre modifiche di bersaglio — PBP2a, precursori van e lipide A — senza scambiarle tra loro.', slides:[
    {label:'Il principio',title:'Se il bersaglio cambia, il farmaco lega meno',intro:'Molti antibiotici funzionano perché riconoscono una struttura. Una modifica di quella struttura abbassa l’affinità. Il batterio non “impara” il farmaco: una variante del bersaglio, già presente o acquisita, diventa più frequente oppure entra nella cellula.',visual:'<div class="compare-pair"><article><b>Bersaglio</b><strong>affinità alta</strong><p>Il farmaco riconosce la struttura.</p></article><i aria-hidden="true">→</i><article><b>Bersaglio modificato</b><strong>affinità ridotta</strong><p>Lo stesso farmaco lega peggio.</p></article></div>',takeaway:'La modifica è specifica del bersaglio. Non rende la cellula resistente a tutte le classi.',sources:[['Blair et al. · Nat Rev Microbiol 2015','https://doi.org/10.1038/nrmicro3380']]},
    {label:'PBP2a',title:'mecA produce una PBP che i β-lattamici usuali legano male',intro:'In Staphylococcus aureus, mecA codifica PBP2a, una proteina di legame alla penicillina con bassa affinità per la maggior parte dei β-lattamici. È la base molecolare della meticillino-resistenza classica. Esiste anche mecC, un omologo meno comune, descritto in isolati da animali e persone.',visual:'<div class="mechanism-grid"><article><strong>Gene usuale</strong><p>mecA, PBP2a.</p></article><article><strong>Omologo</strong><p>mecC, da non dare per assente solo perché mecA non c’è.</p></article><article><strong>Non spiega</strong><p>La resistenza alla vancomicina o alla colistina.</p></article></div>',takeaway:'MRSA nomina un fenotipo. mecA nomina un determinante. Vanno dichiarati entrambi, se entrambi sono stati cercati.',sources:[['Lakhundi e Zhang · Clin Microbiol Rev 2018','https://doi.org/10.1128/CMR.00020-18'],['García-Álvarez et al. · Lancet Infect Dis 2011','https://doi.org/10.1016/S1473-3099(11)70126-8']]},
    {label:'Vancomicina',title:'vanA e vanB cambiano il precursore della parete',intro:'La vancomicina lega il terminale D-Ala-D-Ala del precursore del peptidoglicano. I cluster vanA e vanB fanno sostituire quel terminale con D-Ala-D-Lac, e l’affinità cade. È una modifica del bersaglio, frequente negli enterococchi, non una β-lattamasi.',visual:'<div class="selection-flow"><span>D-Ala-D-Ala</span><i>→</i><span>vanA / vanB</span><i>→</i><span>D-Ala-D-Lac</span></div>',takeaway:'Un enterococco resistente alla vancomicina non è un MRSA con un altro nome.',sources:[['Courvalin · Clin Infect Dis 2006','https://doi.org/10.1086/491711']]},
    {label:'mcr',title:'mcr modifica il lipide A, il bersaglio delle polimixine',intro:'mcr-1, descritto nel 2016, codifica una fosfoetanolammina transferasi che aggiunge un gruppo al lipide A. La colistina, carica positivamente, interagisce meno. Il gene è stato trovato su plasmidi, quindi può muoversi per coniugazione, entro i limiti dell’ospite e del plasmide.',visual:'<div class="mechanism-grid"><article><strong>Bersaglio</strong><p>Lipide A, non le PBP.</p></article><article><strong>Enzima</strong><p>Fosfoetanolammina transferasi, gene mcr.</p></article><article><strong>Mobilità</strong><p>Descritta su plasmide. La presenza non prova un trasferimento recente.</p></article></div>',takeaway:'mcr riguarda la colistina. Non è una carbapenemasi e non si legge su un test per i β-lattamici.',sources:[['Liu et al. · Lancet Infect Dis 2016','https://doi.org/10.1016/S1473-3099(15)00424-7']]},
    {label:'Non si scambiano',title:'Ogni modifica spiega una classe di farmaci',intro:'PBP2a spiega la scarsa affinità di molti β-lattamici. Il terminale D-Ala-D-Lac spiega i glicopeptidi che riconoscono D-Ala-D-Ala. Il lipide A modificato spiega le polimixine. Un isolato può averne più di una, ma ciascuna va dimostrata per conto suo.',visual:'<div class="system-compare"><article><b>PBP2a</b><span>β-lattamici</span><small>mecA, mecC</small></article><article><b>D-Ala-D-Lac</b><span>glicopeptidi</span><small>vanA, vanB</small></article><article><b>Lipide A</b><span>polimixine</span><small>mcr o via cromosomica</small></article></div>',takeaway:'La coesistenza è possibile. L’inferenza dall’una all’altra no.',sources:[['Blair et al. · Nat Rev Microbiol 2015','https://doi.org/10.1038/nrmicro3380'],['Courvalin · Clin Infect Dis 2006','https://doi.org/10.1086/491711'],['Liu et al. · Lancet Infect Dis 2016','https://doi.org/10.1016/S1473-3099(15)00424-7']]},
    {label:'Nel referto',title:'Il bersaglio modificato è un’ipotesi molecolare',intro:'Il fenotipo resta la categoria S, I o R per quel farmaco e quello standard. Il gene indica una spiegazione compatibile, se il metodo lo ha cercato e se l’identificazione di specie rende il gene interpretabile.',visual:'<div class="quote-panel"><p>Fenotipo</p><span>risposta misurata</span><hr><p>Determinante</p><span>mecA, vanA, mcr, se cercato</span><hr><p>Non scritto</p><span>ciò che il pannello non include</span></div>',takeaway:'Un pannello negativo esclude i bersagli del pannello, non tutti i meccanismi.',sources:[['Lakhundi e Zhang · Clin Microbiol Rev 2018','https://doi.org/10.1128/CMR.00020-18'],['EUCAST · Clinical breakpoints','https://www.eucast.org/clinical_breakpoints/']]}
  ]},
  19: { title:'Pompe di efflusso e porine', label:'Ventesimo modulo completo.', completion:'Sei scene per separare l’uscita del farmaco dal suo ingresso, e per non chiamare carbapenemasi ogni calo di suscettibilità.', slides:[
    {label:'Due porte',title:'Il farmaco deve entrare e non essere espulso',intro:'Nei Gram-negativi la membrana esterna filtra l’ingresso attraverso le porine. Le pompe di efflusso riportano substrati verso l’esterno. Ridurre l’ingresso o aumentare l’uscita abbassa la concentrazione utile, senza distruggere la molecola.',visual:'<div class="sci-svg"><svg viewBox="0 0 640 210" role="img" aria-label="Schema dell’involucro batterico con una porina e una pompa di efflusso"><rect x="70" y="48" width="500" height="120" rx="58" fill="#eef6f7" stroke="#2b918e" stroke-width="8"/><rect x="110" y="78" width="420" height="60" rx="28" fill="#ffffff" stroke="#1558b0" stroke-width="2"/><rect x="196" y="40" width="26" height="136" rx="8" fill="#ffffff" stroke="#102f55" stroke-width="2"/><path d="M430 108 H548" stroke="#b4772d" stroke-width="3"/><path d="M536 100 L556 108 L536 116" fill="#b4772d"/><text x="209" y="30" text-anchor="middle" fill="#102f55" font-size="13" font-family="Inter, sans-serif">porina</text><text x="500" y="96" text-anchor="middle" fill="#b4772d" font-size="13" font-family="Inter, sans-serif">efflusso</text><text x="320" y="112" text-anchor="middle" fill="#1558b0" font-size="13" font-family="Inter, sans-serif">periplasma</text></svg><p class="sci-caption">Schema. Non è in scala e non è un ceppo.</p></div>',takeaway:'Porina e pompa agiscono sulla concentrazione, non sull’anello β-lattamico.',sources:[['Li, Plésiat e Nikaido · Clin Microbiol Rev 2015','https://doi.org/10.1128/CMR.00117-14']]},
    {label:'Porine',title:'Meno canali, meno ingresso per alcune molecole',intro:'Le porine sono canali acquosi. In Pseudomonas aeruginosa la perdita di OprD è un esempio classico di ridotto ingresso dell’imipenem. Non tutte le porine trasportano tutti i farmaci: il difetto è selettivo, non una chiusura generica della cellula.',visual:'<div class="mechanism-grid"><article><strong>OprD</strong><p>Porina di P. aeruginosa legata all’ingresso dell’imipenem.</p></article><article><strong>Selettività</strong><p>Un canale in meno non blocca ogni classe.</p></article><article><strong>Da solo</strong><p>Spesso non basta a spiegare una resistenza clinica alta.</p></article></div>',takeaway:'Nominare la porina solo se il dato, genetico o fenotipico, la riguarda.',sources:[['Li, Plésiat e Nikaido · Clin Microbiol Rev 2015','https://doi.org/10.1128/CMR.00117-14']]},
    {label:'Pompe',title:'I sistemi RND esportano substrati diversi',intro:'AcrAB-TolC in Escherichia coli e MexAB-OprM in P. aeruginosa sono pompe tripartite della famiglia RND. Il loro spettro è ampio: β-lattamici, fluorochinoloni, altri composti, in misura diversa. L’aumento di espressione è spesso regolatorio, non soltanto l’arrivo di un gene nuovo.',visual:'<div class="compare-pair"><article><b>E. coli</b><strong>AcrAB-TolC</strong><p>Pompa RND di riferimento.</p></article><i aria-hidden="true">↔</i><article><b>P. aeruginosa</b><strong>MexAB-OprM</strong><p>Pompa RND di riferimento.</p></article></div>',takeaway:'Una pompa può contribuire a un fenotipo multiplo. Non dimostra, da sola, quali geni siano acquisiti.',sources:[['Li, Plésiat e Nikaido · Clin Microbiol Rev 2015','https://doi.org/10.1128/CMR.00117-14']]},
    {label:'Senza carbapenemasi',title:'Porina e β-lattamasi possono bastare a spostare la MIC',intro:'È documentato che la perdita di porine, insieme a un’ESBL o a un’AmpC, può ridurre la suscettibilità ai carbapenemi anche in assenza di una carbapenemasi. Cercare solo KPC, NDM o OXA-48 non esaurisce le spiegazioni di un fenotipo.',visual:'<div class="evidence-ladder"><span>β-lattamasi</span><i>+</i><span>meno porine</span><i>→</i><strong>MIC più alta</strong><small>anche senza carbapenemasi</small></div>',takeaway:'Un test genico negativo per le carbapenemasi note non rende l’isolato suscettibile.',sources:[['Queenan e Bush · Clin Microbiol Rev 2007','https://doi.org/10.1128/CMR.00001-07'],['Li, Plésiat e Nikaido · Clin Microbiol Rev 2015','https://doi.org/10.1128/CMR.00117-14']]},
    {label:'Che cosa misurare',title:'Espressione, sequenza e fenotipo non coincidono',intro:'Una mutazione in un regolatore, una delezione di porina e una MIC sono tre osservazioni. Collegarle richiede la specie, il farmaco e un metodo dichiarato. Un database che annota una pompa non misura la sua espressione in quel ceppo.',visual:'<div class="checklist-visual"><span>specie</span><span>farmaco</span><span>porina o pompa</span><span>fenotipo</span><strong>il nesso va argomentato</strong></div>',takeaway:'Non promuovere un gene di pompa a causa del fenotipo senza il ponte sperimentale.',sources:[['Li, Plésiat e Nikaido · Clin Microbiol Rev 2015','https://doi.org/10.1128/CMR.00117-14']]},
    {label:'La frase',title:'Ingresso e uscita si dichiarano a parte dall’enzima',intro:'Un referto completo può dire: categoria per il carbapeneme, carbapenemasi cercate e non trovate, e se porine o efflusso sono stati studiati. Se non sono stati studiati, si dice che non sono stati studiati.',visual:'<div class="quote-panel"><p>Idrolisi</p><span>l’enzima distrugge la molecola</span><hr><p>Porina</p><span>ne entra meno</span><hr><p>Pompa</p><span>ne esce di più</span></div>',takeaway:'Tre meccanismi, tre frasi. Il fenotipo resta la misura per la cura.',sources:[['EUCAST · Clinical breakpoints','https://www.eucast.org/clinical_breakpoints/'],['Blair et al. · Nat Rev Microbiol 2015','https://doi.org/10.1038/nrmicro3380']]}
  ]},
  20: { title:'Geni mobili', label:'Ventunesimo modulo completo.', completion:'Sei scene per non confondere il gene, il plasmide che lo porta, l’integrone che lo cattura e il trasposone che lo sposta.', slides:[
    {label:'Quattro oggetti',title:'Il gene non è l’elemento che lo muove',intro:'Un gene di resistenza è una sequenza. Può stare sul cromosoma o su un replicone. A spostarlo possono essere un plasmide, un trasposone o una sequenza di inserzione. A raccoglierlo in una cassetta può essere un integrone. Sono livelli diversi della stessa osservazione.',visual:'<div class="scale-ladder"><span>gene</span><i>↕</i><span>cassetta</span><i>↕</i><span>trasposone</span><i>↕</i><span>plasmide</span></div>',takeaway:'Dire “è mobile” senza dire quale elemento è stato visto è una ipotesi, non un risultato.',sources:[['Partridge et al. · Clin Microbiol Rev 2018','https://doi.org/10.1128/CMR.00088-17']]},
    {label:'Plasmidi',title:'Un plasmide è un replicone, non un sinonimo di resistenza',intro:'I plasmidi sono DNA extracromosomico capace di replicarsi. Alcuni sono coniugativi, altri solo mobilizzabili, altri non si trasferiscono da soli. Possono non portare alcun gene di resistenza. Quando lo portano, il contesto del replicone conta quanto il gene.',visual:'<div class="gene-transfer"><article><span class="bacterium"></span><strong>Cellula</strong><small>cromosoma</small></article><span class="plasmid">plasmide</span><article><span class="bacterium recipient"></span><strong>Replicone</strong><small>può essere coniugativo o no</small></article></div>',takeaway:'Annotare “plasmidico” solo se l’assemblato o l’esperimento localizza il gene fuori dal cromosoma.',sources:[['Partridge et al. · Clin Microbiol Rev 2018','https://doi.org/10.1128/CMR.00088-17']]},
    {label:'Integroni',title:'L’integrone cattura cassette; non è lui stesso il gene di resistenza',intro:'Un integrone è un sistema di ricombinazione sito-specifica: integrasi, sito di attacco, promotore. Le cassette geniche si inseriscono in fila. Gli integroni di classe 1 sono quelli più spesso trovati insieme a cassette di resistenza negli isolati clinici.',visual:'<div class="selection-flow"><span>intI</span><i>→</i><span>attI</span><i>→</i><span>cassetta</span><i>→</i><span>cassetta</span></div>',takeaway:'Trovare intI1 non elenca le cassette. Le cassette vanno sequenziate.',sources:[['Partridge et al. · Clin Microbiol Rev 2018','https://doi.org/10.1128/CMR.00088-17']]},
    {label:'Trasposoni',title:'Trasposoni e sequenze di inserzione spostano tratti di DNA',intro:'I trasposoni e le IS si muovono, o muovono il DNA adiacente, con una trasposasi. Un caso più volte ricostruito è ISEcp1 a monte di blaCTX-M: la sequenza di inserzione può mobilizzare il gene della β-lattamasi. È una ricostruzione di struttura, non la prova di un salto avvenuto nel campione di ieri.',visual:'<div class="evidence-ladder"><span>ISEcp1</span><i>→</i><span>blaCTX-M</span><i>→</i><strong>struttura compatibile con la mobilizzazione</strong></div>',takeaway:'La struttura spiega come il gene possa essersi mosso. Non data l’evento.',sources:[['Partridge et al. · Clin Microbiol Rev 2018','https://doi.org/10.1128/CMR.00088-17']]},
    {label:'Co-localizzazione',title:'Stare sullo stesso elemento non è un trasferimento osservato',intro:'Due geni sullo stesso plasmide possono essere co-selezionati. Questo non dimostra che il plasmide sia passato di cellula durante lo studio, né che entrambi i geni siano espressi. Per un trasferimento servono disegno sperimentale o epidemiologia, non solo la mappa.',visual:'<div class="communication-pair"><article><b>Si può dire</b><p>Questi geni sono sullo stesso contig o sullo stesso replicone, se l’assemblato lo regge.</p></article><article><b>Non si può dire</b><p>Che il passaggio sia avvenuto nel paziente, nell’allevamento o nel refluo campionato.</p></article></div>',takeaway:'La mappa genetica e la storia del contagio sono evidenze diverse.',sources:[['Partridge et al. · Clin Microbiol Rev 2018','https://doi.org/10.1128/CMR.00088-17']]},
    {label:'Come riportarlo',title:'Elemento, evidenza, limite',intro:'Una frase utilizzabile dice: gene, elemento se risolto, metodo con cui la localizzazione è stata ottenuta, e che cosa resta ambiguo quando i contig sono corti. I read brevi spesso non chiudono un plasmide.',visual:'<div class="quote-panel"><p>Gene</p><span>qual è</span><hr><p>Supporto</p><span>cromosoma, plasmide, non risolto</span><hr><p>Metodo</p><span>assemblato, lettura lunga, esperimento</span></div>',takeaway:'“Non risolto” è un risultato. È meglio di una mobilità presunta.',sources:[['Partridge et al. · Clin Microbiol Rev 2018','https://doi.org/10.1128/CMR.00088-17'],['Boolchandani, D’Souza e Dantas · Nat Rev Genet 2019','https://doi.org/10.1038/s41576-019-0108-4']]}
  ]},
  21: { title:'Trasferimento orizzontale', label:'Ventiduesimo modulo completo.', completion:'Sei scene per distinguere coniugazione, trasformazione e trasduzione, e per non chiamare trasferimento una semplice co-presenza.', slides:[
    {label:'Tre vie',title:'Il DNA passa per contatto, per rilascio o per un fago',intro:'Il trasferimento orizzontale è il passaggio di DNA tra cellule che non sono in rapporto madre-figlia. Le tre vie classiche hanno requisiti diversi: un contatto per la coniugazione, competenza e DNA libero per la trasformazione, un batteriofago per la trasduzione. Nessuna è automatica.',visual:'<div class="mechanism-grid"><article><strong>Coniugazione</strong><p>Contatto e, di solito, un sistema di secrezione di tipo IV.</p></article><article><strong>Trasformazione</strong><p>DNA extracellulare e una cellula competente.</p></article><article><strong>Trasduzione</strong><p>Un fago che impacchetta DNA batterico.</p></article></div>',takeaway:'Nominare la via solo se il disegno dello studio può distinguerla.',sources:[['von Wintersdorff et al. · Front Microbiol 2016','https://doi.org/10.3389/fmicb.2016.00173'],['Thomas e Nielsen · Nat Rev Microbiol 2005','https://doi.org/10.1038/nrmicro1234']]},
    {label:'Coniugazione',title:'Serve un donatore, un ricevente e un macchinario',intro:'I plasmidi coniugativi e gli elementi integrativi coniugativi portano i geni del trasferimento. Il ricevente deve essere compatibile con il replicone. Dopo l’ingresso, restrizione, incompatibilità plasmidica e costo del replicone decidono se il DNA resta.',visual:'<div class="gene-transfer"><article><span class="bacterium"></span><strong>Donatore</strong><small>plasmide coniugativo o ICE</small></article><i aria-hidden="true">→</i><span class="plasmid">DNA</span><i aria-hidden="true">→</i><article><span class="bacterium recipient"></span><strong>Ricevente</strong><small>se il replicone è compatibile</small></article></div>',takeaway:'Un gene su un plasmide coniugativo è trasferibile in linea di principio, non trasferito in quel campione.',sources:[['Thomas e Nielsen · Nat Rev Microbiol 2005','https://doi.org/10.1038/nrmicro1234']]},
    {label:'Trasformazione',title:'Solo alcune specie prendono DNA nudo in modo efficiente',intro:'La competenza naturale è una proprietà fisiologica, descritta tra gli altri in Streptococcus pneumoniae, Neisseria, Haemophilus e Acinetobacter. Non è lo stato normale di ogni batterio in un refluo o in un ospedale. Il DNA libero, inoltre, deve essere abbastanza integro.',visual:'<div class="selection-flow"><span>DNA libero</span><i>→</i><span>competenza</span><i>→</i><span>ingresso</span><i>→</i><span>integrazione o replicone</span></div>',takeaway:'Trovare DNA libero e un batterio nello stesso campione non è una trasformazione osservata.',sources:[['von Wintersdorff et al. · Front Microbiol 2016','https://doi.org/10.3389/fmicb.2016.00173']]},
    {label:'Trasduzione',title:'Il fago è un vettore, non una prova di direzione',intro:'Nella trasduzione un capside impacchetta DNA del batterio ospite e può iniettarlo in un’altra cellula sensibile a quel fago. Lo spettro d’ospite del fago limita il passaggio. Rilevare un fago e un gene di resistenza non ricostruisce, da solo, il ciclo.',visual:'<div class="evidence-ladder"><span>cellula infetta</span><i>→</i><span>capside</span><i>→</i><span>nuova cellula</span><i>→</i><strong>solo se il fago la infetta</strong></div>',takeaway:'La trasduzione è una via biologica documentata. Non è l’interpretazione di default di un gene ambientale.',sources:[['von Wintersdorff et al. · Front Microbiol 2016','https://doi.org/10.3389/fmicb.2016.00173']]},
    {label:'Le barriere',title:'La cellula non accetta qualsiasi DNA',intro:'Thomas e Nielsen riassumono barriere che il trasferimento deve superare: restrizione e modifica, sistemi come CRISPR, incompatibilità tra plasmidi, differenze di ospite. Per questo la stessa sequenza non circola con la stessa probabilità in ogni specie.',visual:'<div class="checklist-visual"><span>restrizione</span><span>CRISPR</span><span>incompatibilità</span><span>spettro d’ospite</span><strong>il passaggio può fallire</strong></div>',takeaway:'L’assenza di un trasferimento non contraddice la presenza del macchinario.',sources:[['Thomas e Nielsen · Nat Rev Microbiol 2005','https://doi.org/10.1038/nrmicro1234']]},
    {label:'La parola',title:'Rilevato, trasferibile, trasferito',intro:'“Rilevato” descrive il metodo e il campione. “Trasferibile” descrive una struttura compatibile con una via. “Trasferito” descrive un evento, e chiede tempo, donatore, ricevente e un disegno che li colleghi.',visual:'<div class="quote-panel"><p>Rilevato</p><span>nel campione, con quel metodo</span><hr><p>Trasferibile</p><span>struttura compatibile con una via</span><hr><p>Trasferito</p><span>evento da documentare a parte</span></div>',takeaway:'Le tre parole non si abbreviano l’una nell’altra.',sources:[['Thomas e Nielsen · Nat Rev Microbiol 2005','https://doi.org/10.1038/nrmicro1234'],['von Wintersdorff et al. · Front Microbiol 2016','https://doi.org/10.3389/fmicb.2016.00173']]}
  ]},
  22: { title:'Co-selezione', label:'Ventitreesimo modulo completo.', completion:'Sei scene per distinguere co-resistenza, cross-resistenza e co-regolazione, senza trattare un metallo o un biocida come prova di selezione.', slides:[
    {label:'Tre meccanismi',title:'Co-selezione non è una sola cosa',intro:'Baker-Austin e colleghi separano tre situazioni. Nella co-resistenza, geni diversi stanno sullo stesso elemento genetico. Nella cross-resistenza, un solo meccanismo, per esempio una pompa, riconosce composti diversi. Nella co-regolazione, gli stessi segnali accendono più risposte.',visual:'<div class="mechanism-grid"><article><strong>Co-resistenza</strong><p>Geni diversi, stesso elemento.</p></article><article><strong>Cross-resistenza</strong><p>Un meccanismo, più substrati.</p></article><article><strong>Co-regolazione</strong><p>Circuiti di controllo condivisi.</p></article></div>',takeaway:'Se non si sa quale dei tre è in gioco, si dice co-selezione solo come ipotesi.',sources:[['Baker-Austin et al. · Trends Microbiol 2006','https://doi.org/10.1016/j.tim.2006.02.006']]},
    {label:'Metalli',title:'Geni per metalli e geni per antibiotici co-occorrono spesso',intro:'Analisi di genomi e plasmidi trovano ripetutamente, sugli stessi elementi, determinanti per rame, zinco, argento o mercurio e geni di resistenza agli antibiotici. Pal e colleghi lo mostrano come co-occorrenza bioinformatica. La co-occorrenza non misura la concentrazione di metallo che ha selezionato quel plasmide.',visual:'<div class="matrix-grid"><span>rame</span><span>zinco</span><span>argento</span><span>mercurio</span><b>co-occorrenza con geni AMR · non una dose di campo</b></div>',takeaway:'Un metallo nel campione e un gene nel campione restano due misure finché il legame genetico non è mostrato.',sources:[['Pal et al. · BMC Genomics 2015','https://doi.org/10.1186/s12864-015-2153-5'],['Baker-Austin et al. · Trends Microbiol 2006','https://doi.org/10.1016/j.tim.2006.02.006']]},
    {label:'Biocidi',title:'Alcuni geni per biocidi viaggiano con cassette di resistenza',intro:'Geni che riducono la suscettibilità ai composti di ammonio quaternario, come i qac, sono stati descritti sugli integroni di classe 1 insieme a cassette di resistenza agli antibiotici. È un fatto di struttura genetica. Non quantifica l’effetto di un disinfettante in un reparto o in un impianto.',visual:'<div class="selection-flow"><span>classe 1</span><i>→</i><span>cassetta AMR</span><i>+</i><span>qac</span></div>',takeaway:'La struttura autorizza l’ipotesi di co-resistenza. Non autorizza ad attribuire un focolaio a un biocida.',sources:[['Partridge et al. · Clin Microbiol Rev 2018','https://doi.org/10.1128/CMR.00088-17'],['Pal et al. · BMC Genomics 2015','https://doi.org/10.1186/s12864-015-2153-5']]},
    {label:'Residui',title:'In laboratorio la selezione può avvenire sotto la MIC',intro:'Gullberg e colleghi hanno mostrato, in competizioni sperimentali, che concentrazioni di antibiotico ben al di sotto della MIC possono selezionare mutanti resistenti. È un risultato di laboratorio, con coppie antibiotico-ceppo definite. Non è una soglia di scarico e non è una misura nelle acque sarde.',visual:'<div class="denominator-card"><strong>Sotto la MIC</strong><span>selezione osservata in competizione sperimentale</span><hr><span>Gullberg et al. 2011 · non una concentrazione di campo</span><b>non trasferire il numero a un refluo</b></div>',takeaway:'Il risultato sposta la domanda, non fornisce il limite da applicare a un territorio.',sources:[['Gullberg et al. · PLoS Pathog 2011','https://doi.org/10.1371/journal.ppat.1002158']]},
    {label:'Nel campione',title:'Tre osservazioni non sono ancora un meccanismo',intro:'Un residuo di antibiotico, un metallo e un gene di resistenza nello stesso campione possono essere compatibili con la co-selezione. Per sostenerla servono il collegamento genetico, oppure un esperimento, e un denominatore. La compatibilità non è la dimostrazione.',visual:'<div class="evidence-ladder"><span>co-presenza</span><i>→</i><span>ipotesi</span><i>→</i><span>legame genetico o esperimento</span><i>→</i><strong>co-selezione argomentata</strong></div>',takeaway:'Fermarsi al gradino che i dati raggiungono.',sources:[['Baker-Austin et al. · Trends Microbiol 2006','https://doi.org/10.1016/j.tim.2006.02.006']]},
    {label:'La frase',title:'Dire che cosa è stato misurato',intro:'Una frase utilizzabile separa la concentrazione chimica, il gene, l’elemento genetico e l’eventuale esperimento. Se manca un pezzo, la co-selezione resta una domanda, non una conclusione del monitoraggio.',visual:'<div class="quote-panel"><p>Chimica</p><span>quale composto, quale metodo</span><hr><p>Genetica</p><span>quali geni, se sullo stesso elemento</span><hr><p>Selezione</p><span>solo se un disegno la sostiene</span></div>',takeaway:'La prudenza rende il dato riutilizzabile. Non lo svuota.',sources:[['Pal et al. · BMC Genomics 2015','https://doi.org/10.1186/s12864-015-2153-5'],['Gullberg et al. · PLoS Pathog 2011','https://doi.org/10.1371/journal.ppat.1002158']]}
  ]},
  23: { title:'Dall’antibiogramma al gene', label:'Ventiquattresimo modulo completo.', completion:'Sei scene per tenere fenotipo e genotipo come misure diverse, e per leggere la discordanza come informazione.', slides:[
    {label:'Fenotipo',title:'S, I e R sono categorie di un test, non un gene',intro:'L’antibiogramma misura la risposta di un isolato a un farmaco in condizioni dichiarate. EUCAST traduce quella misura in categorie interpretative con breakpoint pubblicati. La categoria vale per quell’isolato, quel farmaco, quel metodo e quella versione dei breakpoint.',visual:'<div class="ast-strip"><span class="ast-s">S</span><p><b>Sensibile</b><small>esposizione standard, secondo lo standard usato</small></p><span class="ast-i">I</span><p><b>Sensibile ad aumentata esposizione</b><small>nella definizione EUCAST corrente</small></p><span class="ast-r">R</span><p><b>Resistente</b><small>alta probabilità di fallimento terapeutico</small></p></div>',takeaway:'Cambiare breakpoint o metodo può cambiare la lettera senza che il batterio sia cambiato.',sources:[['EUCAST · Clinical breakpoints','https://www.eucast.org/clinical_breakpoints/']]},
    {label:'Genotipo',title:'Il genotipo è una sequenza o una mutazione cercata',intro:'Un gene, una mutazione in una regione determinante o un allele di un bersaglio sono osservazioni di sequenza. Dicono che quel determinante è presente nel materiale esaminato, entro i limiti del metodo. Non dicono, da soli, la categoria S, I o R.',visual:'<div class="compare-pair"><article><b>Fenotipo</b><strong>risposta misurata</strong><p>Farmaco, inoculo, soglia.</p></article><i aria-hidden="true">↔</i><article><b>Genotipo</b><strong>sequenza rilevata</strong><p>Pannello, profondità, database.</p></article></div>',takeaway:'Le due colonne del referto non sono traduzioni automatiche l’una dell’altra.',sources:[['Anjum, Zankari e Hasman · Microbiol Spectr 2017','https://doi.org/10.1128/microbiolspec.ARBA-0011-2017']]},
    {label:'Quando concordano',title:'La concordanza è utile e non è universale',intro:'Per alcuni determinanti la corrispondenza con il fenotipo è stretta: mecA e la meticillino-resistenza di S. aureus ne è l’esempio più citato, con l’eccezione già ricordata di mecC. Per molte β-lattamasi, pompe e porine la corrispondenza dipende da espressione e contesto.',visual:'<div class="conclusion-board"><span class="yes">concordanza attesa, da dichiarare</span><span class="yes">gene noto e fenotipo coerente</span><span class="no">gene presente, farmaco ancora attivo</span><span class="no">fenotipo resistente, gene del pannello assente</span></div>',takeaway:'La regola di corrispondenza è specifica del determinante. Non si esporta da mecA a ogni bla.',sources:[['Lakhundi e Zhang · Clin Microbiol Rev 2018','https://doi.org/10.1128/CMR.00020-18'],['Anjum, Zankari e Hasman · Microbiol Spectr 2017','https://doi.org/10.1128/microbiolspec.ARBA-0011-2017']]},
    {label:'Quando divergono',title:'La discordanza è un risultato, non un errore di default',intro:'Un gene può non essere espresso. Un meccanismo può non essere nel pannello. Una popolazione può essere eterogenea. Il database può non contenere la variante. Ognuna di queste spiegazioni si distingue con un controllo, non cancellando una delle due misure.',visual:'<div class="checklist-visual"><span>espressione</span><span>pannello incompleto</span><span>eterogeneità</span><span>database</span><strong>dichiarare quale ipotesi è stata controllata</strong></div>',takeaway:'Non “correggere” il fenotipo con il gene, né il gene con il fenotipo, senza dire che cosa si è verificato.',sources:[['Anjum, Zankari e Hasman · Microbiol Spectr 2017','https://doi.org/10.1128/microbiolspec.ARBA-0011-2017'],['EUCAST · Clinical breakpoints','https://www.eucast.org/clinical_breakpoints/']]},
    {label:'In sorveglianza',title:'Il sequenziamento completa la sorveglianza, non la sostituisce',intro:'L’OMS, nella guida GLASS sul sequenziamento, tratta il genoma come uno strumento di sorveglianza della resistenza accanto ai dati fenotipici. Il confronto tra laboratori richiede metodi, versioni e denominatori allineati, esattamente come per le percentuali di resistenza.',visual:'<div class="surveillance-flow"><span>isolato</span><i>→</i><span>fenotipo</span><i>→</i><span>genoma</span><i>→</i><span>indicatore</span></div>',takeaway:'Un indicatore genomico senza la popolazione osservata non è una prevalenza.',sources:[['WHO · GLASS whole-genome sequencing','https://www.who.int/publications/i/item/9789240011007'],['WHO · GLASS','https://www.who.int/initiatives/glass']]},
    {label:'La scheda',title:'Metodo e versione fanno parte del dato',intro:'Una scheda riutilizzabile riporta lo standard dei breakpoint e la data, il pannello o il database e la versione, e che cosa non è stato cercato. È lo stesso criterio con cui l’Atlante chiede fonte e limite prima di un confronto.',visual:'<div class="quote-panel"><p>Fenotipo</p><span>standard e versione dei breakpoint</span><hr><p>Genotipo</p><span>pannello o database e versione</span><hr><p>Non cercato</p><span>va scritto, non lasciato implicito</span></div>',takeaway:'Il dato si confronta solo con un dato che dichiara le stesse scelte.',sources:[['EUCAST · Clinical breakpoints','https://www.eucast.org/clinical_breakpoints/'],['WHO · GLASS whole-genome sequencing','https://www.who.int/publications/i/item/9789240011007']]}
  ]},
  24: { title:'PCR e qPCR', label:'Venticinquesimo modulo completo.', completion:'Sei scene per dire che cosa una PCR e una qPCR misurano, e che cosa una curva non diventa.', slides:[
    {label:'PCR',title:'La PCR risponde a una domanda chiusa',intro:'L’amplificazione end-point chiede se una sequenza scelta, definita dai primer, è rilevabile nel materiale, sopra la soglia pratica di quella reazione. Non cerca i geni che i primer non riconoscono e non dice se il batterio che li portava fosse vitale.',visual:'<div class="selection-flow"><span>primer</span><i>→</i><span>bersaglio</span><i>→</i><span>prodotto</span><i>→</i><span>presenza o assenza</span></div>',takeaway:'Un risultato positivo è “questa sequenza, in questo pozzetto”. Non è un antibiogramma.',sources:[['Anjum, Zankari e Hasman · Microbiol Spectr 2017','https://doi.org/10.1128/microbiolspec.ARBA-0011-2017']]},
    {label:'qPCR',title:'La quantità è relativa a una curva o a un riferimento',intro:'La PCR quantitativa segue il segnale a ogni ciclo e lo riporta a una curva di calibrazione o a un gene di riferimento. Il numero che ne esce è una stima di copie della sequenza bersaglio, con l’incertezza del metodo. Non è un conteggio di cellule vive e non è un’incidenza.',visual:'<div class="sci-svg"><svg viewBox="0 0 640 180" role="img" aria-label="Schema di amplificazione senza scala numerica"><path d="M40 150 C140 148 180 140 230 110 C280 78 320 40 600 28" fill="none" stroke="#1558b0" stroke-width="3"/><text x="40" y="28" fill="#66798d" font-size="13" font-family="Inter, sans-serif">segnale</text><text x="520" y="168" fill="#66798d" font-size="13" font-family="Inter, sans-serif">cicli</text></svg><p class="sci-caption">Schema. Nessun numero di copie: la scala dipende dalla curva, che qui non c’è.</p></div>',takeaway:'Pubblicare il numero senza la curva, i primer e il controllo di inibizione lo rende illeggibile.',sources:[['Anjum, Zankari e Hasman · Microbiol Spectr 2017','https://doi.org/10.1128/microbiolspec.ARBA-0011-2017']]},
    {label:'Che cosa non è',title:'Copie, cellule e persone sono tre denominatori',intro:'Una copia di gene può stare in una cellula morta, in un DNA libero, in un batterio non patogeno o in più copie sullo stesso plasmide. Nessuno di questi casi è un paziente. Il passaggio da copie a rischio richiede altri dati, che la qPCR non contiene.',visual:'<div class="risk-chain"><span>copie</span><i>→</i><span>cellula</span><i>→</i><span>persona</span><i>→</i><strong>non è il risultato della qPCR</strong></div>',takeaway:'Fermare la frase alle copie della sequenza bersaglio.',sources:[['Boolchandani, D’Souza e Dantas · Nat Rev Genet 2019','https://doi.org/10.1038/s41576-019-0108-4']]},
    {label:'Controlli',title:'Senza controllo di inibizione il negativo non si interpreta',intro:'Acque reflue, feci e alimenti possono inibire la polimerasi. Un controllo di amplificazione interno, o un altro controllo di inibizione, dice se un negativo è “bersaglio non rilevato” oppure “reazione non valutabile”. I controlli negativi dicono se c’è contaminazione.',visual:'<div class="clinical-path"><article><span>01</span><strong>Negativo</strong><p>contaminazione</p></article><i>→</i><article><span>02</span><strong>Positivo</strong><p>la reazione può funzionare</p></article><i>→</i><article><span>03</span><strong>Inibizione</strong><p>il campione non spegne la PCR</p></article></div>',takeaway:'Un negativo senza controllo di inibizione non è una assenza.',sources:[['Anjum, Zankari e Hasman · Microbiol Spectr 2017','https://doi.org/10.1128/microbiolspec.ARBA-0011-2017']]},
    {label:'Il pannello',title:'Ciò che non è nel pannello non può risultare positivo',intro:'Una PCR multipla resta un elenco finito di bersagli. Un campione “negativo” è negativo per quei primer, in quelle condizioni. Nuove varianti che i primer non riconoscono, e geni non inclusi, restano fuori dal risultato.',visual:'<div class="communication-pair"><article><b>Dentro il pannello</b><p>Presenza o assenza di ciascuna sequenza, se i controlli reggono.</p></article><article><b>Fuori dal pannello</b><p>Nessuna informazione. Non è un dato negativo.</p></article></div>',takeaway:'Allegare l’elenco dei bersagli fa parte del riportare il risultato.',sources:[['Anjum, Zankari e Hasman · Microbiol Spectr 2017','https://doi.org/10.1128/microbiolspec.ARBA-0011-2017']]},
    {label:'La scheda di metodo',title:'Primer, soglia e matrice si scrivono',intro:'Due laboratori che amplificano “blaNDM” possono usare primer diversi e matrici diverse. Il confronto delle serie richiede gli stessi bersagli, o una dichiarazione esplicita della differenza. Non serve inventare un limite di rilevazione unico: serve quello del saggio usato.',visual:'<div class="quote-panel"><p>Bersaglio</p><span>primer o riferimento della sequenza</span><hr><p>Matrice</p><span>isolato, acqua, feci</span><hr><p>Soglia del saggio</p><span>quella dichiarata dal metodo, non una soglia generica</span></div>',takeaway:'La qPCR è precisa quando il metodo viaggia insieme al numero.',sources:[['Anjum, Zankari e Hasman · Microbiol Spectr 2017','https://doi.org/10.1128/microbiolspec.ARBA-0011-2017']]}
  ]},
  25: { title:'WGS e tipizzazione', label:'Ventiseiesimo modulo completo.', completion:'Sei scene per usare MLST e cgMLST come scale di parentela, non come prove di trasmissione.', slides:[
    {label:'Il genoma',title:'Il sequenziamento descrive l’isolato che è stato coltivato',intro:'Il whole genome sequencing parte, in questa accezione, da un isolato. La qualità dell’assemblato, la copertura e la contaminazione fanno parte del risultato. Un genoma non rappresenta il reparto, l’allevamento o il bacino fognario da cui il campione proviene.',visual:'<div class="surveillance-flow"><span>campione</span><i>→</i><span>isolato</span><i>→</i><span>letture</span><i>→</i><span>assemblato</span></div>',takeaway:'La domanda “di chi è questo genoma” si risponde con la scheda del campione, non con l’albero.',sources:[['WHO · GLASS whole-genome sequencing','https://www.who.int/publications/i/item/9789240011007'],['Boolchandani, D’Souza e Dantas · Nat Rev Genet 2019','https://doi.org/10.1038/s41576-019-0108-4']]},
    {label:'MLST',title:'Pochi geni housekeeping descrivono un lignaggio',intro:'La multilocus sequence typing, introdotta da Maiden e colleghi, assegna alleli a un piccolo insieme di geni housekeeping e condensa il profilo in un sequence type. È fatta per confrontare lignaggi nel tempo e tra laboratori. Non è risolta abbastanza per un focolaio stretto.',visual:'<div class="denominator-card"><strong>ST</strong><span>profilo allelico di geni housekeeping</span><hr><span>Maiden et al. 1998 · scala di lignaggio, non di catena di contagio</span><b>lo schema e la versione vanno citati</b></div>',takeaway:'Due isolati con lo stesso ST sono dello stesso lignaggio. Non sono lo stesso evento di trasmissione.',sources:[['Maiden et al. · PNAS 1998','https://doi.org/10.1073/pnas.95.6.3140'],['Jolley, Bray e Maiden · Wellcome Open Res 2018','https://doi.org/10.12688/wellcomeopenres.14826.1']]},
    {label:'cgMLST',title:'Molti loci del genoma core alzano la risoluzione',intro:'La core-genome MLST estende il principio degli alleli a centinaia o migliaia di loci presenti nella maggior parte dei genomi di quella specie. Serve a confrontare isolati vicini. Lo schema è specie-specifico: un numero di alleli di differenza non si importa da un patogeno all’altro.',visual:'<div class="compare-pair"><article><b>MLST</b><strong>lignaggio</strong><p>Pochi loci. Sequence type.</p></article><i aria-hidden="true">→</i><article><b>cgMLST</b><strong>confronto fine</strong><p>Molti loci core. Schema della specie.</p></article></div>',takeaway:'Una distanza allelica è il prodotto di uno schema. Senza il nome dello schema non è interpretabile.',sources:[['Schürch et al. · Clin Microbiol Infect 2018','https://doi.org/10.1016/j.cmi.2017.12.016'],['Jolley, Bray e Maiden · Wellcome Open Res 2018','https://doi.org/10.12688/wellcomeopenres.14826.1']]},
    {label:'SNP e alleli',title:'Due modi di contare le differenze, non due verità',intro:'Schürch e colleghi confrontano l’approccio per polimorfismi di singolo nucleotide e quello gene-per-gene. Cambiano il riferimento, il filtro sulle regioni ripetute e il modo in cui una differenza viene contata. Allineare i metodi è una condizione del confronto, non un dettaglio.',visual:'<div class="communication-pair"><article><b>SNP</b><p>Differenze rispetto a un riferimento, dopo filtri dichiarati.</p></article><article><b>Alleli</b><p>Differenze di locus in uno schema cgMLST.</p></article></div>',takeaway:'Non mediare una distanza SNP con una distanza allelica.',sources:[['Schürch et al. · Clin Microbiol Infect 2018','https://doi.org/10.1016/j.cmi.2017.12.016']]},
    {label:'La soglia',title:'Una soglia di focolaio non è un numero universale',intro:'Alcuni protocolli usano una soglia di alleli o di SNP per definire un cluster. Quella soglia dipende dalla specie, dallo schema, dal tempo e dalla domanda. Importarla da un altro patogeno, o da un altro laboratorio, senza dichiararla, produce cluster non confrontabili.',visual:'<div class="evidence-ladder"><span>distanza</span><i>→</i><span>soglia dello schema</span><i>→</i><span>ipotesi di cluster</span><i>→</i><strong>epidemiologia</strong></div>',takeaway:'Il cluster genomico è un’ipotesi. Luogo, tempo e vie plausibili restano necessari.',sources:[['Schürch et al. · Clin Microbiol Infect 2018','https://doi.org/10.1016/j.cmi.2017.12.016'],['WHO · GLASS whole-genome sequencing','https://www.who.int/publications/i/item/9789240011007']]},
    {label:'La banca',title:'PubMLST e lo schema sono parte della citazione',intro:'Jolley, Bray e Maiden descrivono PubMLST e BIGSdb come l’infrastruttura pubblica degli schemi. Citare “MLST” senza specie, schema e data dell’interrogazione non permette di rifare il profilo. Lo stesso vale per un cgMLST locale.',visual:'<div class="quote-panel"><p>Specie</p><span>e schema</span><hr><p>Versione</p><span>della banca, alla data dell’analisi</span><hr><p>Distanza</p><span>con la soglia, se una soglia è stata usata</span></div>',takeaway:'Il tipo di sequenza è un risultato riproducibile solo se lo schema è riproducibile.',sources:[['Jolley, Bray e Maiden · Wellcome Open Res 2018','https://doi.org/10.12688/wellcomeopenres.14826.1'],['PubMLST','https://pubmlst.org/']]}
  ]},
  26: { title:'Metagenomica e resistoma', label:'Ventisettesimo modulo completo.', completion:'Sei scene per leggere un resistoma come l’insieme delle sequenze di resistenza in un campione, non come un’infezione.', slides:[
    {label:'La parola',title:'Resistoma è l’insieme dei determinanti nel campione',intro:'Wright ha usato “resistoma” per l’insieme dei determinanti di resistenza, compresi quelli ambientali che non stanno in un patogeno. In un campione metagenomico la parola indica le sequenze riconosciute come tali dal metodo e dal database. Non indica batteri vivi, né casi clinici.',visual:'<div class="resistome-cloud"><span>bla</span><span>tet</span><span>sul</span><span>mcr</span><span>qnr</span><b>sequenze, non infezioni</b></div>',takeaway:'Il resistoma è una descrizione del DNA esaminato.',sources:[['Wright · Nat Rev Microbiol 2007','https://doi.org/10.1038/nrmicro1614']]},
    {label:'Il metodo',title:'La shotgun non coltiva e non sceglie una specie',intro:'Nella metagenomica shotgun si sequenzia il DNA della comunità, senza isolare. Il risultato dipende da estrazione, profondità e da come le letture vengono confrontate con un catalogo. Due profondità diverse non sono due resistomi direttamente confrontabili.',visual:'<div class="surveillance-flow"><span>comunità</span><i>→</i><span>estrazione</span><i>→</i><span>letture</span><i>→</i><span>catalogo</span></div>',takeaway:'Profondità e catalogo si scrivono accanto all’elenco dei geni.',sources:[['Boolchandani, D’Souza e Dantas · Nat Rev Genet 2019','https://doi.org/10.1038/s41576-019-0108-4']]},
    {label:'Letture o geni',title:'Mappare letture e assemblare non producono lo stesso oggetto',intro:'Si possono mappare letture corte su un database, oppure assemblare e poi annotare i contig. Le letture corte raramente dicono quale specie porta il gene. L’assemblato può risolverlo solo se il contig è abbastanza lungo e non è chimerico.',visual:'<div class="compare-pair"><article><b>Letture</b><strong>abbondanza relativa</strong><p>Dipende dal database e dalla profondità.</p></article><i aria-hidden="true">↔</i><article><b>Assemblato</b><strong>contesto, se il contig regge</strong><p>L’ospite del gene spesso resta ambiguo.</p></article></div>',takeaway:'Non attribuire un gene a una specie se il metodo non risolve l’ospite.',sources:[['Boolchandani, D’Souza e Dantas · Nat Rev Genet 2019','https://doi.org/10.1038/s41576-019-0108-4']]},
    {label:'Il database',title:'Si vede ciò che il catalogo contiene',intro:'CARD, ResFinder e AMRFinderPlus, nel modulo 30, non hanno le stesse regole di inclusione. Un resistoma “completo” è completo rispetto al catalogo e alla versione usati. I geni non ancora depositati, e le mutazioni cromosomiche mal coperte, restano fuori.',visual:'<div class="filter-visual"><span>catalogo</span><span>versione</span><span>soglia di identità</span><strong>il resistoma è condizionato da queste tre scelte</strong></div>',takeaway:'Cambiare catalogo cambia l’elenco. La differenza va dichiarata, non interpretata come biologia.',sources:[['Alcock et al. · Nucleic Acids Res 2023','https://doi.org/10.1093/nar/gkac920'],['Boolchandani, D’Souza e Dantas · Nat Rev Genet 2019','https://doi.org/10.1038/s41576-019-0108-4']]},
    {label:'Un uso reale',title:'Fognature urbane confrontate con lo stesso metodo',intro:'Hendriksen e colleghi hanno confrontato metagenomi di acque reflue urbane in molte città per descrivere resistomi. Il confronto regge perché il disegno è comune. Non converte un gene in un tasso di infezione della città, e non si estende a un singolo impianto non incluso.',visual:'<div class="benefit-grid"><article><b>Si può</b><p>confrontare campioni analizzati nello stesso modo</p></article><article><b>Non si può</b><p>leggere un’abbondanza come incidenza clinica</p></article><article><b>Serve</b><p>luogo, data, profondità, catalogo</p></article></div>',takeaway:'Una serie metagenomica descrive sequenze. Il rischio è un’altra valutazione.',sources:[['Hendriksen et al. · Nat Commun 2019','https://doi.org/10.1038/s41467-019-08853-3']]},
    {label:'La frase',title:'Abbondanza relativa non è vitalità e non è rischio',intro:'La frase precisa è: in questo campione, con questa profondità e questo catalogo, queste sequenze sono state rilevate a questa abbondanza relativa. Tutto il resto — specie ospite, cellula viva, esposizione, infezione — chiede evidenze che il resistoma non contiene.',visual:'<div class="quote-panel"><p>Rilevato</p><span>sequenza, catalogo, soglia</span><hr><p>Non risolto</p><span>ospite, vitalità, copia per cellula</span><hr><p>Non misurato</p><span>infezione o esposizione di una persona</span></div>',takeaway:'Il resistoma diventa più forte quando non gli si chiede di essere un referto.',sources:[['Wright · Nat Rev Microbiol 2007','https://doi.org/10.1038/nrmicro1614'],['Hendriksen et al. · Nat Commun 2019','https://doi.org/10.1038/s41467-019-08853-3']]}
  ]},
  27: { title:'Sorveglianza delle acque reflue', label:'Ventottesimo modulo completo.', completion:'Sei scene per fissare che cosa un campione di refluo autorizza a dire, e che cosa resta fuori dal dato.', slides:[
    {label:'Il campione',title:'Il refluo è un composito di chi scarica in quella rete',intro:'Un campione di acque reflue mescola contributi di persone, e a volte di altre immissioni, servite da quell’impianto in quell’ora. Non è un prelievo clinico e non è la somma dei comuni attraversati da un fiume. La popolazione servita va documentata, non dedotta dal confine amministrativo.',visual:'<div class="sci-svg"><svg viewBox="0 0 640 180" role="img" aria-label="Schema di contributi che confluiscono in un campione di refluo"><rect x="40" y="36" width="70" height="36" fill="#ffffff" stroke="#1558b0"/><rect x="140" y="36" width="70" height="36" fill="#ffffff" stroke="#1558b0"/><rect x="240" y="36" width="70" height="36" fill="#ffffff" stroke="#1558b0"/><path d="M75 72 V100 H275 V72" fill="none" stroke="#2b918e" stroke-width="2"/><path d="M175 100 V118 H430" fill="none" stroke="#102f55" stroke-width="2"/><rect x="408" y="86" width="44" height="64" rx="4" fill="#eef6f7" stroke="#102f55"/><text x="75" y="28" text-anchor="middle" fill="#102f55" font-size="12" font-family="Inter, sans-serif">contributo</text><text x="175" y="28" text-anchor="middle" fill="#102f55" font-size="12" font-family="Inter, sans-serif">contributo</text><text x="275" y="28" text-anchor="middle" fill="#102f55" font-size="12" font-family="Inter, sans-serif">contributo</text><text x="500" y="108" fill="#102f55" font-size="13" font-family="Inter, sans-serif">campione</text></svg><p class="sci-caption">Schema. I contributi non sono persone identificate.</p></div>',takeaway:'Il denominatore geografico del refluo è il bacino servito, se è noto.',sources:[['WHO · Environmental dimensions of AMR','https://www.who.int/publications/i/item/9789240052352'],['Hendriksen et al. · Nat Commun 2019','https://doi.org/10.1038/s41467-019-08853-3']]},
    {label:'Che cosa dice',title:'Dice che cosa è stato rilevato, dove e con quale metodo',intro:'Un segnale positivo dice che il bersaglio — un gene, una sequenza, a volte un patogeno cercato — era rilevabile in quel campione, sopra la soglia del saggio, in quel momento. Se il campionamento si ripete con lo stesso metodo, la serie può descrivere un andamento nel refluo. Non descrive, da sola, un andamento clinico.',visual:'<div class="source-card-visual"><b>dove</b><span>punto e ora del prelievo</span><b>che cosa</b><span>bersaglio e metodo</span><b>serie</b><span>solo se i campioni sono confrontabili</span></div>',takeaway:'La frase minima è già un risultato: rilevato, in quel campione, con quel metodo.',sources:[['Hendriksen et al. · Nat Commun 2019','https://doi.org/10.1038/s41467-019-08853-3'],['WHO · GLASS','https://www.who.int/initiatives/glass']]},
    {label:'Che cosa non dice',title:'Non identifica la persona e non misura l’incidenza',intro:'Dal refluo non si risale a chi ha escreto il bersaglio, a quanti sono i casi, alla vitalità del batterio, né — se il metodo è una PCR o un read corto — alla specie che porta il gene. Non misura l’esposizione di chi vive vicino all’impianto. Non dimostra che l’impianto “produca” resistenza.',visual:'<div class="communication-pair"><article><b>Si può dire</b><p>Bersaglio rilevato nel composito, con soglia e metodo dichiarati.</p></article><article><b>Non si può dire</b><p>Chi è infetto, quanti sono i casi, se la cellula era viva, se il gene era in un patogeno.</p></article></div>',takeaway:'Il salto da “rilevato nel refluo” a “rischio per il territorio” non è nel dato.',sources:[['WHO · Environmental dimensions of AMR','https://www.who.int/publications/i/item/9789240052352']]},
    {label:'Il denominatore',title:'Portata e marcatori fecali cambiano la lettura',intro:'Una concentrazione per litro dipende dalla diluizione. Per avvicinarsi a un segnale per persona servono la portata e un marcatore di feci umane, e la scelta del marcatore fa parte del metodo. Senza questi elementi il numero resta una concentrazione del campione, non un tasso.',visual:'<div class="denominator-card"><strong>copie / litro</strong><span>concentrazione nel campione</span><hr><span>portata e marcatore fecale, se usati, sono un altro denominatore</span><b>non è un’incidenza</b></div>',takeaway:'Non confrontare concentrazioni di giorni con piogge o portate diverse senza dirlo.',sources:[['WHO · Environmental dimensions of AMR','https://www.who.int/publications/i/item/9789240052352'],['Boolchandani, D’Souza e Dantas · Nat Rev Genet 2019','https://doi.org/10.1038/s41576-019-0108-4']]},
    {label:'Il negativo',title:'Non rilevato non è assente nella popolazione',intro:'Diluizione, escrezione intermittente, inibizione della PCR e un pannello che non include il bersaglio producono negativi anche se il determinante circola. Vale la stessa regola dell’Atlante: un risultato vuoto è “nessuna evidenza compatibile con questo metodo”, non “assenza di AMR”.',visual:'<div class="checklist-visual"><span>diluizione</span><span>escrezione</span><span>inibizione</span><span>pannello</span><strong>negativo del saggio, non assenza</strong></div>',takeaway:'Il negativo si riporta con la soglia del saggio e il controllo di inibizione.',sources:[['Anjum, Zankari e Hasman · Microbiol Spectr 2017','https://doi.org/10.1128/microbiolspec.ARBA-0011-2017'],['WHO · Environmental dimensions of AMR','https://www.who.int/publications/i/item/9789240052352']]},
    {label:'Come si usa',title:'Osservazione, interpretazione e azione restano separate',intro:'Il refluo può affiancare la sorveglianza clinica e veterinaria, come contesto di popolazione servita, quando la serie è stabile. Non sostituisce AR-ISS, non localizza un reparto e non indica un antibiotico. L’azione, se serve, si decide con i sistemi che hanno un denominatore clinico.',visual:'<div class="quote-panel"><p>Osservazione</p><span>bersaglio, campione, metodo</span><hr><p>Interpretazione</p><span>andamento nel bacino servito, se la serie lo regge</span><hr><p>Azione</p><span>non si deduce dal singolo campione</span></div>',takeaway:'La sorveglianza ambientale è utile nella misura in cui non le si chiede di essere una diagnosi.',sources:[['WHO · GLASS','https://www.who.int/initiatives/glass'],['ECDC · EARS-Net','https://www.ecdc.europa.eu/en/about-us/partnerships-and-networks/disease-and-laboratory-networks/ears-net']]}
  ]},
  28: { title:'Nanopore sul campo', label:'Ventinovesimo modulo completo.', completion:'Sei scene per collocare il sequenziamento a nanopori tra portabilità e lettura lunga, senza scambiare un segnale in corso d’opera per un referto.', slides:[
    {label:'Che cos’è',title:'Letture lunghe, e un flusso di basi durante la corsa',intro:'Il sequenziamento a nanopori legge filamenti lunghi e può mostrare le basi mentre la corsa prosegue. Gli strumenti portatili sono stati usati fuori dal laboratorio centrale: Quick e colleghi lo hanno fatto per la sorveglianza di Ebola. Quell’esperienza riguarda un virus e una rete di laboratorio, non una prestazione clinica generica.',visual:'<div class="selection-flow"><span>molecola lunga</span><i>→</i><span>poro</span><i>→</i><span>basi in corso d’opera</span></div>',takeaway:'“In tempo reale” descrive l’arrivo delle basi. Non descrive la validazione del risultato.',sources:[['Quick et al. · Nature 2016','https://doi.org/10.1038/nature16996']]},
    {label:'Perché la lunghezza conta',title:'Una lettura lunga può tenere insieme gene e contesto',intro:'Ashton e colleghi hanno usato MinION per collocare un’isola di resistenza e la sua struttura. La lunghezza aiuta dove le letture corte spezzano plasmide, trasposone e gene. Aiuta se la lettura copre davvero quel tratto e se l’assemblato non è chimerico.',visual:'<div class="evidence-ladder"><span>lettura lunga</span><i>→</i><span>gene e fianchi</span><i>→</i><strong>contesto, se la copertura regge</strong></div>',takeaway:'La lunghezza è un vantaggio di struttura. Non è una garanzia di assegnazione alla specie.',sources:[['Ashton et al. · Nat Biotechnol 2014','https://doi.org/10.1038/nbt.3103']]},
    {label:'In clinica',title:'Anche in ospedale il flusso non chiude da solo la diagnosi',intro:'Charalampous e colleghi hanno usato metagenomica a nanopori per infezioni respiratorie basse, geni di resistenza compresi, dentro un percorso di laboratorio. Il lavoro mostra un uso rapido. Non elimina coltura, fenotipo e giudizio clinico, e non è un protocollo da copiare fuori dal suo disegno.',visual:'<div class="clinical-path"><article><span>01</span><strong>Campione</strong><p>respiratorio, nello studio</p></article><i>→</i><article><span>02</span><strong>Letture</strong><p>ipotesi di patogeno e geni</p></article><i>→</i><article><span>03</span><strong>Contesto</strong><p>laboratorio e clinica</p></article></div>',takeaway:'Un metodo pubblicato per una matrice non è un metodo validato per tutte le matrici.',sources:[['Charalampous et al. · Nat Biotechnol 2019','https://doi.org/10.1038/s41587-019-0156-5']]},
    {label:'Il preliminare',title:'Un match a metà corsa è un’ipotesi di sequenza',intro:'Durante la corsa un confronto con un database può proporre un gene. Quella proposta dipende dalla basecaller, dalla copertura accumulata e dalla versione del database. Le mutazioni puntiformi, per esempio in un gene bersaglio, chiedono consenso. Un match precoce non è una categoria S, I o R.',visual:'<div class="communication-pair"><article><b>Si può dire</b><p>A questo punto della corsa, con questo database, c’è un match preliminare.</p></article><article><b>Non si può dire</b><p>Che l’isolato sia resistente, né che il risultato sia chiuso.</p></article></div>',takeaway:'Tenere la parola “preliminare” finché copertura, controlli e database non sono dichiarati.',sources:[['Ashton et al. · Nat Biotechnol 2014','https://doi.org/10.1038/nbt.3103'],['Boolchandani, D’Souza e Dantas · Nat Rev Genet 2019','https://doi.org/10.1038/s41576-019-0108-4']]},
    {label:'Errori e controlli',title:'Chimica e basecaller cambiano il profilo di errore',intro:'L’accuratezza delle letture a nanopori è migliorata con le chimiche e i software, e resta diversa da quella delle piattaforme a letture corte. Non citiamo una percentuale: dipende da chimica, basecaller e data, e invecchia in fretta. Contaminazione e scambio di barcode restano controlli di laboratorio, anche se lo strumento è portatile.',visual:'<div class="checklist-visual"><span>chimica</span><span>basecaller</span><span>copertura</span><span>controllo negativo</span><strong>fanno parte del risultato</strong></div>',takeaway:'La portabilità non rimuove il controllo negativo né la versione del software.',sources:[['Quick et al. · Nature 2016','https://doi.org/10.1038/nature16996'],['Charalampous et al. · Nat Biotechnol 2019','https://doi.org/10.1038/s41587-019-0156-5']]},
    {label:'Sul campo',title:'Lo strumento esce dal laboratorio; la domanda no',intro:'Un sequenziatore portatile può produrre letture vicino al prelievo. L’interpretazione chiede ancora la scheda del campione, il database con la data, il controllo negativo e una domanda che il disegno può reggere. Senza questi elementi la lettura lunga è un file, non una sorveglianza.',visual:'<div class="quote-panel"><p>File</p><span>letture, chimica, basecaller</span><hr><p>Confronto</p><span>database e versione</span><hr><p>Domanda</p><span>quella che il campionamento può sostenere</span></div>',takeaway:'Tempo reale e campo descrivono la logistica. La validità resta un fatto di metodo.',sources:[['Quick et al. · Nature 2016','https://doi.org/10.1038/nature16996'],['WHO · GLASS whole-genome sequencing','https://www.who.int/publications/i/item/9789240011007']]}
  ]},
  29: { title:'Banche dati e strumenti', label:'Trentesimo modulo completo.', completion:'Sei scene per usare CARD, ResFinder e AMRFinderPlus come cataloghi con regole diverse, e per citare versione e data.', slides:[
    {label:'Tre cataloghi',title:'Non cercano la stessa cosa',intro:'CARD, ResFinder e AMRFinderPlus interrogano sequenze contro raccolte curate di determinanti. Differiscono per ciò che includono: geni acquisiti, mutazioni cromosomiche, geni intrinseci, e per come graduano un match incerto. Un disaccordo tra strumenti può essere una differenza di regole.',visual:'<div class="system-compare"><article><b>CARD</b><span>ontologia</span><small>RGI, match graduati</small></article><article><b>ResFinder</b><span>geni acquisiti</span><small>e, in 4.0, un modello di fenotipo</small></article><article><b>AMRFinderPlus</b><span>NCBI</span><small>geni e mutazioni di specie</small></article></div>',takeaway:'Il nome dello strumento senza la versione non è un metodo.',sources:[['Alcock et al. · Nucleic Acids Res 2023','https://doi.org/10.1093/nar/gkac920'],['Bortolaia et al. · J Antimicrob Chemother 2020','https://doi.org/10.1093/jac/dkaa345'],['Feldgarden et al. · Sci Rep 2021','https://doi.org/10.1038/s41598-021-91456-0']]},
    {label:'CARD',title:'Perfect, strict e loose non sono lo stesso match',intro:'CARD organizza i determinanti nell’Antibiotic Resistance Ontology e li cerca con il Resistance Gene Identifier. Un match perfect, uno strict e uno loose non hanno la stessa forza. Il loose è un’omologia più lontana: si riporta come tale, non si promuove a gene presente.',visual:'<div class="evidence-ladder"><span>loose</span><i>→</i><span>strict</span><i>→</i><span>perfect</span><i>→</i><strong>forza del match, non del fenotipo</strong></div>',takeaway:'La categoria del match fa parte del risultato. Ometterla cambia il senso della riga.',sources:[['Alcock et al. · Nucleic Acids Res 2023','https://doi.org/10.1093/nar/gkac920'],['CARD','https://card.mcmaster.ca/']]},
    {label:'ResFinder',title:'Il gene acquisito e il fenotipo predetto sono due uscite',intro:'ResFinder, descritto da Zankari e colleghi, identifica geni di resistenza acquisiti. ResFinder 4.0 aggiunge una predizione di fenotipo e si appoggia a PointFinder per mutazioni cromosomiche selezionate. La predizione è l’uscita di un modello. Non è la categoria EUCAST di quell’isolato.',visual:'<div class="compare-pair"><article><b>Gene</b><strong>acquisito, se i criteri sono soddisfatti</strong><p>Zankari et al. 2012.</p></article><i aria-hidden="true">≠</i><article><b>Fenotipo predetto</b><strong>uscita del modello 4.0</strong><p>Non è un antibiogramma.</p></article></div>',takeaway:'Tenere la predizione in una colonna diversa dal fenotipo misurato.',sources:[['Zankari et al. · J Antimicrob Chemother 2012','https://doi.org/10.1093/jac/dks261'],['Bortolaia et al. · J Antimicrob Chemother 2020','https://doi.org/10.1093/jac/dkaa345']]},
    {label:'AMRFinderPlus',title:'Geni, mutazioni di specie, e un “plus” che non è AMR',intro:'AMRFinderPlus, sul Reference Gene Catalog dell’NCBI, cerca geni acquisiti e mutazioni puntiformi specifiche di organismo. Può anche riportare geni di stress, biocidi, metalli e virulenza. Quei geni non vanno messi nell’elenco della resistenza se l’analisi non li ha separati.',visual:'<div class="checklist-visual"><span>gene AMR</span><span>mutazione di specie</span><span>stress o metallo</span><span>virulenza</span><strong>solo i primi due sono resistenza</strong></div>',takeaway:'Il flag “plus” si filtra prima di contare i determinanti di resistenza.',sources:[['Feldgarden et al. · Sci Rep 2021','https://doi.org/10.1038/s41598-021-91456-0'],['NCBI · AMRFinderPlus','https://www.ncbi.nlm.nih.gov/pathogens/antimicrobial-resistance/AMRFinder/']]},
    {label:'Il disaccordo',title:'Tre elenchi diversi possono essere tutti coerenti con le proprie regole',intro:'Lo stesso assemblato può dare un gene in uno strumento e non nell’altro, per una soglia di identità, per l’inclusione dei determinanti intrinseci, o per una mutazione che solo uno dei tre cataloga. La differenza si spiega confrontando le regole. Non si risolve votando a maggioranza.',visual:'<div class="communication-pair"><article><b>Confronto lecito</b><p>Stesso assemblato, regole e versioni affiancate, differenza spiegata.</p></article><article><b>Confronto illecito</b><p>Sommare i geni dei tre strumenti, o scegliere il numero più alto.</p></article></div>',takeaway:'Il disaccordo è un dato di metodo. Si pubblica, non si nasconde.',sources:[['Boolchandani, D’Souza e Dantas · Nat Rev Genet 2019','https://doi.org/10.1038/s41576-019-0108-4'],['Feldgarden et al. · Sci Rep 2021','https://doi.org/10.1038/s41598-021-91456-0']]},
    {label:'La citazione',title:'Strumento, versione, database, data',intro:'Una riga riutilizzabile contiene il nome dello strumento, la versione del programma, la versione del database e la data dell’analisi, più la soglia se non è quella di default. Il match che ne esce non è un antibiogramma e non è un caso. L’Atlante chiede lo stesso ordine di precisione alle altre fonti.',visual:'<div class="quote-panel"><p>Strumento</p><span>CARD, ResFinder o AMRFinderPlus</span><hr><p>Versione</p><span>programma e database, con la data</span><hr><p>Non è</p><span>una categoria S, I, R, né una diagnosi</span></div>',takeaway:'Il catalogo rende il gene confrontabile. Non gli aggiunge un significato clinico che non ha.',sources:[['Alcock et al. · Nucleic Acids Res 2023','https://doi.org/10.1093/nar/gkac920'],['Bortolaia et al. · J Antimicrob Chemother 2020','https://doi.org/10.1093/jac/dkaa345'],['Feldgarden et al. · Sci Rep 2021','https://doi.org/10.1038/s41598-021-91456-0']]}
  ]}
});
